1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
6	<title>轨道跑者 — Rail Runner</title>
7	<style>
8	  * { margin:0; padding:0; box-sizing:border-box; }
9	  html, body { width:100%; height:100%; overflow:hidden; background:#1a1a2e; }
10	  body {
11	    display:flex; justify-content:center; align-items:center;
12	    font-family:'Segoe UI','PingFang SC',sans-serif;
13	  }
14	  #game-container {
15	    position:relative;
16	    width:100vmin; max-width:600px;
17	    height:100vmin; max-height:900px;
18	    aspect-ratio:2/3;
19	  }
20	  canvas {
21	    display:block; width:100%; height:100%;
22	    touch-action:manipulation;
23	    image-rendering:auto;
24	  }
25	</style>
26	</head>
27	<body>
28	
29	<div id="game-container">
30	  <canvas id="game"></canvas>
31	</div>
32	
33	<script>
34	/* ==========================================================================
35	   轨道跑者 — Rail Runner  v0.1 Tier 1
36	   2.5D 等距视角无限跑酷 | HTML5 Canvas | 60fps | 零依赖
37	   ========================================================================== */
38	
39	/* =========================== 命名空间 =========================== */
40	const G = {
41	  canvas: null,
42	  ctx: null,
43	  W: 0, H: 0,
44	
45	  /* 游戏状态 */
46	  state: 'start',     // start | playing | dead
47	  score: 0,
48	  highScore: 0,
49	  distance: 0,
50	  speed: 0,
51	  hearts: 3,
52	  invincible: 0,       // 剩余无敌帧数
53	
54	  /* 玩家 */
55	  player: null,
56	
57	  /* 对象池 */
58	  obstacles: [],
59	  coins: [],
60	  particles: [],
61	
62	  /* 输入 */
63	  keys: {},
64	  swipeStart: null,
65	  lastSwipe: '',
66	
67	  /* 世界参数 */
68	  vanishY: 0,          // 消失点 Y
69	  vanishX: 0,          // 消失点 X
70	  maxDist: 800,        // 最大可视距离
71	  laneSpread: 0,       // 轨道底部扩散宽度
72	  groundY: 0,          // 玩家地面位置 Y（屏幕坐标）
73	
74	  /* 生成控制 */
75	  spawnTimer: 0,
76	  spawnInterval: 60,   // 初始帧间隔
77	  coinTimer: 0,
78	
79	  /* 帧率 */
80	  lastTime: 0,
81	  deltaTime: 0,
82	  fps: 0,
83	  frameCount: 0,
84	  fpsTime: 0,
85	
86	  /* 离线画布 */
87	  offscreen: {},
88	};
89	
90	/* =========================== 常量 =========================== */
91	const LANE_COUNT = 3;
92	const PLAYER_LANE = 1;     // 玩家初始在中间轨道 (0=左, 1=中, 2=右)
93	const MAX_HEARTS = 3;
94	const INVINCIBLE_FRAMES = 90;  // 1.5秒 @ 60fps
95	const BASE_SPEED = 3.5;
96	const MAX_SPEED = 14;
97	const SPEED_INC = 0.0004;      // 每帧加速量
98	const DISTANCE_PER_FRAME = 0.6; // 每帧距离增量（米）
99	const COIN_SCORE = 50;
100	const DISTANCE_SCORE = 1;       // 每米分数
101	
102	/* 玩家动作状态 */
103	const STATE_RUN = 'run';
104	const STATE_JUMP = 'jump';
105	const STATE_SLIDE = 'slide';
106	const STATE_HIT = 'hit';
107	
108	/* 障碍物类型 */
109	const OBS_LOW = 'low';       // 滑铲通过
110	const OBS_MID = 'mid';       // 跳跃通过
111	const OBS_HIGH = 'high';     // 必须换道
112	
113	/* =========================== 工具函数 =========================== */
114	function lerp(a, b, t) { return a + (b - a) * t; }
115	function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
116	function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
117	function randChoice(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
118	
119	/* 屏幕坐标：根据世界深度计算 screenY 和缩放比例 */
120	function worldToScreen(dist) {
121	  /* dist: 0 = 玩家脚下, maxDist = 地平线 */
122	  const t = 1 - clamp(dist / G.maxDist, 0, 1);
123	  const screenY = lerp(G.vanishY, G.groundY, t);
124	  const scale = lerp(0.15, 1.0, t);
125	  return { y: screenY, scale };
126	}
127	
128	/* 轨道 X 坐标：根据深度 + 轨道索引计算 screenX */
129	function laneX(laneIdx, dist) {
130	  const t = 1 - clamp(dist / G.maxDist, 0, 1);
131	  const spread = lerp(0, G.laneSpread, t);
132	  const centerX = G.vanishX;
133	  return centerX + (laneIdx - 1) * spread;
134	}
135	
136	/* =========================== 初始化 =========================== */
137	function init() {
138	  G.canvas = document.getElementById('game');
139	  G.ctx = G.canvas.getContext('2d', { alpha: false });
140	  resize();
141	  window.addEventListener('resize', resize);
142	
143	  /* 加载最高分 */
144	  try {
145	    G.highScore = parseInt(localStorage.getItem('railRunner_highScore')) || 0;
146	  } catch(e) { G.highScore = 0; }
147	
148	  /* 输入：键盘 */
149	  window.addEventListener('keydown', e => {
150	    G.keys[e.key] = true;
151	    if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
152	      e.preventDefault();
153	    }
154	    if (G.state === 'start' && e.key === ' ') startGame();
155	    if (G.state === 'dead' && e.key === ' ') restartGame();
156	  });
157	  window.addEventListener('keyup', e => { G.keys[e.key] = false; });
158	
159	  /* 输入：触屏 */
160	  G.canvas.addEventListener('touchstart', e => {
161	    e.preventDefault();
162	    if (G.state === 'start') { startGame(); return; }
163	    if (G.state === 'dead') { restartGame(); return; }
164	    const t = e.touches[0];
165	    G.swipeStart = { x: t.clientX, y: t.clientY, time: Date.now() };
166	  }, { passive: false });
167	
168	  G.canvas.addEventListener('touchend', e => {
169	    if (!G.swipeStart) return;
170	    const t = e.changedTouches[0];
171	    const dx = t.clientX - G.swipeStart.x;
172	    const dy = t.clientY - G.swipeStart.y;
173	    const dt = Date.now() - G.swipeStart.time;
174	    const absDx = Math.abs(dx), absDy = Math.abs(dy);
175	
176	    if (Math.max(absDx, absDy) < 20) return; // 太小忽略
177	
178	    if (absDx > absDy) {
179	      G.lastSwipe = dx > 0 ? 'right' : 'left';
180	    } else {
181	      G.lastSwipe = dy > 0 ? 'down' : 'up';
182	    }
183	    G.swipeStart = null;
184	  });
185	
186	  /* 玩家 */
187	  G.player = createPlayer();
188	
189	  /* 预渲染 */
190	  preRenderAssets();
191	
192	  /* 启动循环 */
193	  G.lastTime = performance.now();
194	  requestAnimationFrame(gameLoop);
195	}
196	
197	function resize() {
198	  const container = document.getElementById('game-container');
199	  const rect = container.getBoundingClientRect();
200	  const dpr = Math.min(window.devicePixelRatio || 1, 2); // 限制像素比
201	  G.W = rect.width;
202	  G.H = rect.height;
203	  G.canvas.width = G.W * dpr;
204	  G.canvas.height = G.H * dpr;
205	  G.canvas.style.width = G.W + 'px';
206	  G.canvas.style.height = G.H + 'px';
207	  G.ctx.setTransform(1, 0, 0, 1, 0, 0);
208	  G.ctx.scale(dpr, dpr);
209	
210	  /* 重新计算透视参数 */
211	  G.vanishX = G.W * 0.5;
212	  G.vanishY = G.H * 0.28;
213	  G.groundY = G.H * 0.88;
214	  G.laneSpread = G.W * 0.18;
215	
216	  /* 预渲染需要 resize */
217	  preRenderAssets();
218	}
219	
220	/* =========================== 预渲染资源 =========================== */
221	function preRenderAssets() {
222	  /* --- 天空渐变背景 --- */
223	  const skyCanvas = document.createElement('canvas');
224	  skyCanvas.width = G.W;
225	  skyCanvas.height = G.H;
226	  const skyCtx = skyCanvas.getContext('2d');
227	  const grad = skyCtx.createLinearGradient(0, 0, 0, G.vanishY + 40);
228	  grad.addColorStop(0, '#1a1a4e');
229	  grad.addColorStop(0.5, '#2d4a8e');
230	  grad.addColorStop(1, '#5ba3d9');
231	  skyCtx.fillStyle = grad;
232	  skyCtx.fillRect(0, 0, G.W, G.H);
233	  G.offscreen.sky = skyCanvas;
234	
235	  /* --- 城市天际线（远景） --- */
236	  const cityCanvas = document.createElement('canvas');
237	  cityCanvas.width = G.W * 3; // 宽于屏幕用于视差滚动
238	  cityCanvas.height = G.H * 0.25;
239	  const cityCtx = cityCanvas.getContext('2d');
240	  /* 建筑剪影 */
241	  cityCtx.fillStyle = '#1a1a3e';
242	  const buildings = [];
243	  let bx = 0;
244	  while (bx < cityCanvas.width) {
245	    const bw = randInt(30, 100);
246	    const bh = randInt(40, cityCanvas.height * 0.85);
247	    buildings.push({ x: bx, w: bw, h: bh });
248	    bx += bw + randInt(5, 20);
249	  }
250	  buildings.forEach(b => {
251	    cityCtx.fillRect(b.x, cityCanvas.height - b.h, b.w, b.h);
252	    /* 窗户光点 */
253	    cityCtx.fillStyle = 'rgba(255,220,150,0.3)';
254	    for (let wy = cityCanvas.height - b.h + 8; wy < cityCanvas.height - 8; wy += 12) {
255	      for (let wx = b.x + 6; wx < b.x + b.w - 6; wx += 10) {
256	        if (Math.random() < 0.4) cityCtx.fillRect(wx, wy, 3, 3);
257	      }
258	    }
259	    cityCtx.fillStyle = '#1a1a3e';
260	  });
261	  G.offscreen.city = cityCanvas;
262	
263	  /* --- 近景建筑（更大、暖色调） --- */
264	  const nearCanvas = document.createElement('canvas');
265	  nearCanvas.width = G.W * 2;
266	  nearCanvas.height = G.H * 0.35;
267	  const nearCtx = nearCanvas.getContext('2d');
268	  nearCtx.fillStyle = '#2a1a0a';
269	  let nx = 0;
270	  while (nx < nearCanvas.width) {
271	    const nw = randInt(60, 160);
272	    const nh = randInt(80, nearCanvas.height * 0.9);
273	    nearCtx.fillRect(nx, nearCanvas.height - nh, nw, nh);
274	    /* 更大更亮的窗户 */
275	    nearCtx.fillStyle = 'rgba(255,200,100,0.2)';
276	    for (let wy = nearCanvas.height - nh + 12; wy < nearCanvas.height - 10; wy += 16) {
277	      for (let wx = nx + 10; wx < nx + nw - 10; wx += 14) {
278	        if (Math.random() < 0.35) nearCtx.fillRect(wx, wy, 5, 6);
279	      }
280	    }
281	    nearCtx.fillStyle = '#2a1a0a';
282	    nx += nw + randInt(8, 30);
283	  }
284	  G.offscreen.nearCity = nearCanvas;
285	
286	  /* --- 玩家精灵 预渲染 --- */
287	  G.offscreen.player = {};
288	  ['run', 'jump', 'slide', 'hit'].forEach(state => {
289	    const pc = document.createElement('canvas');
290	    pc.width = 80; pc.height = 100;
291	    drawPlayerSprite(pc.getContext('2d'), state, pc.width, pc.height);
292	    G.offscreen.player[state] = pc;
293	  });
294	
295	  /* --- 障碍物图块 --- */
296	  G.offscreen.obstacles = {};
297	  /* 低障碍（横杆） */
298	  let oc = document.createElement('canvas'); oc.width=60; oc.height=20;
299	  drawObstacleSprite(oc.getContext('2d'), OBS_LOW, oc.width, oc.height);
300	  G.offscreen.obstacles[OBS_LOW] = oc;
301	  /* 中障碍（信号灯箱） */
302	  oc = document.createElement('canvas'); oc.width=40; oc.height=55;
303	  drawObstacleSprite(oc.getContext('2d'), OBS_MID, oc.width, oc.height);
304	  G.offscreen.obstacles[OBS_MID] = oc;
305	  /* 高障碍（信号塔） */
306	  oc = document.createElement('canvas'); oc.width=50; oc.height=120;
307	  drawObstacleSprite(oc.getContext('2d'), OBS_HIGH, oc.width, oc.height);
308	  G.offscreen.obstacles[OBS_HIGH] = oc;
309	
310	  /* --- 金币 --- */
311	  const coinCanvas = document.createElement('canvas');
312	  coinCanvas.width = 32; coinCanvas.height = 32;
313	  drawCoinSprite(coinCanvas.getContext('2d'), coinCanvas.width, coinCanvas.height);
314	  G.offscreen.coin = coinCanvas;
315	
316	  /* --- 粒子 --- */
317	  const partCanvas = document.createElement('canvas');
318	  partCanvas.width = 8; partCanvas.height = 8;
319	  const partCtx = partCanvas.getContext('2d');
320	  partCtx.fillStyle = '#fff';
321	  partCtx.beginPath(); partCtx.arc(4,4,4,0,Math.PI*2); partCtx.fill();
322	  G.offscreen.particle = partCanvas;
323	}
324	
325	/* =========================== 精灵绘制 =========================== */
326	function drawPlayerSprite(ctx, state, w, h) {
327	  ctx.clearRect(0, 0, w, h);
328	  const cx = w/2, cy = h * 0.55;
329	
330	  if (state === STATE_SLIDE) {
331	    /* 压低身体贴地滑铲 */
332	    /* 身体（横卧） */
333	    ctx.fillStyle = '#e94560';
334	    ctx.fillRect(cx-22, cy-8, 44, 18);
335	    /* 连帽衫帽子 */
336	    ctx.fillStyle = '#c23152';
337	    ctx.beginPath(); ctx.arc(cx-14, cy-4, 10, 0, Math.PI*2); ctx.fill();
338	    /* 腿（向后伸展） */
339	    ctx.fillStyle = '#2d2d44';
340	    ctx.fillRect(cx-10, cy+4, 28, 10);
341	    ctx.fillStyle = '#e94560';
342	    ctx.fillRect(cx+14, cy+6, 14, 7);
343	    /* 运动鞋 */
344	    ctx.fillStyle = '#fff';
345	    ctx.fillRect(cx+24, cy+7, 10, 6);
346	    /* 手臂前伸 */
347	    ctx.fillStyle = '#e94560';
348	    ctx.fillRect(cx-28, cy-2, 12, 6);
349	    ctx.fillStyle = '#ffd3b6';
350	    ctx.fillRect(cx-30, cy-3, 6, 5);
351	  } else if (state === STATE_JUMP) {
352	    /* 跳跃腾空蜷缩 */
353	    ctx.fillStyle = '#e94560';
354	    ctx.fillRect(cx-12, cy-30, 24, 32);  // 身体（抬起）
355	    ctx.fillStyle = '#c23152';
356	    ctx.beginPath(); ctx.arc(cx, cy-36, 11, 0, Math.PI*2); ctx.fill(); // 头
357	    /* 腿蜷缩 */
358	    ctx.fillStyle = '#2d2d44';
359	    ctx.fillRect(cx-10, cy+2, 10, 14);
360	    ctx.fillRect(cx+2, cy+2, 10, 14);
361	    ctx.fillStyle = '#e94560';
362	    ctx.fillRect(cx-8, cy, 12, 18);
363	    /* 鞋 */
364	    ctx.fillStyle = '#fff';
365	    ctx.fillRect(cx-7, cy+14, 8, 5);
366	    ctx.fillRect(cx+3, cy+14, 10, 5);
367	    /* 手臂上摆 */
368	    ctx.fillStyle = '#e94560';
369	    ctx.fillRect(cx-18, cy-24, 8, 18);
370	    ctx.fillStyle = '#ffd3b6';
371	    ctx.beginPath(); ctx.arc(cx-14, cy-28, 5, 0, Math.PI*2); ctx.fill();
372	  } else if (state === STATE_HIT) {
373	    /* 被撞后仰 */
374	    ctx.fillStyle = '#ff4444';
375	    ctx.fillRect(cx-8, cy-24, 16, 28);
376	    ctx.fillStyle = '#cc0000';
377	    ctx.beginPath(); ctx.arc(cx, cy-32, 10, 0, Math.PI*2); ctx.fill();
378	    ctx.fillStyle = '#2d2d44';
379	    ctx.fillRect(cx-8, cy+4, 8, 16);
380	    ctx.fillRect(cx+2, cy+4, 8, 14);
381	  } else {
382	    /* 奔跑——默认姿态 */
383	    /* 身体/连帽衫 */
384	    ctx.fillStyle = '#e94560';
385	    ctx.fillRect(cx-10, cy-28, 20, 30);
386	    /* 帽子 */
387	    ctx.fillStyle = '#c23152';
388	    ctx.beginPath(); ctx.arc(cx, cy-34, 11, 0, Math.PI*2); ctx.fill();
389	    /* 脸 */
390	    ctx.fillStyle = '#ffd3b6';
391	    ctx.beginPath(); ctx.arc(cx, cy-32, 7, 0, Math.PI*2); ctx.fill();
392	    /* 裤腿 */
393	    ctx.fillStyle = '#2d2d44';
394	    ctx.fillRect(cx-10, cy+2, 8, 16);
395	    ctx.fillRect(cx+4, cy+2, 8, 14);
396	    /* 鞋 */
397	    ctx.fillStyle = '#fff';
398	    ctx.fillRect(cx-11, cy+15, 10, 6);
399	    ctx.fillRect(cx+3, cy+13, 11, 6);
400	    /* 手臂摆动的腿反侧 */
401	    ctx.fillStyle = '#ffd3b6';
402	    ctx.fillRect(cx-14, cy-18, 5, 12);
