455	/* =========================== 对象池 =========================== */
456	function poolGet(pool, factory) {
457	  for (let i = 0; i < pool.length; i++) {
458	    if (!pool[i].active) { pool[i].active = true; return pool[i]; }
459	  }
460	  const obj = factory();
461	  obj.active = true;
462	  pool.push(obj);
463	  return obj;
464	}
465	
466	function poolReleaseAll(pool) {
467	  for (let i = 0; i < pool.length; i++) pool[i].active = false;
468	}
