560	function hurtPlayer(damage) {
561	  if (G.invincible > 0) return;
562	  G.hearts -= damage;
563	  G.invincible = INVINCIBLE_FRAMES;
564	  if (G.hearts <= 0) {
565	    G.hearts = 0;
566	    die();
567	  } else {
568	    G.player.state = STATE_HIT;
569	    G.player.stateTimer = 18; // 短暂后仰
