573	/* =========================== 输入处理 =========================== */
574	function processInput() {
575	  if (G.state !== 'playing') return;
576	
577	  let moveLR = 0;
578	  let jump = false;
579	  let slide = false;
580	
581	  /* 键盘 */
582	  if (G.keys['ArrowLeft'] || G.keys['a'] || G.keys['A']) moveLR = -1;
583	  if (G.keys['ArrowRight'] || G.keys['d'] || G.keys['D']) moveLR = 1;
584	  if (G.keys['ArrowUp'] || G.keys['w'] || G.keys['W']) jump = true;
585	  if (G.keys['ArrowDown'] || G.keys['s'] || G.keys['S']) slide = true;
586	
587	  /* 触屏 */
588	  if (G.lastSwipe === 'left') { moveLR = -1; G.lastSwipe = ''; }
589	  if (G.lastSwipe === 'right') { moveLR = 1; G.lastSwipe = ''; }
590	  if (G.lastSwipe === 'up') { jump = true; G.lastSwipe = ''; }
591	  if (G.lastSwipe === 'down') { slide = true; G.lastSwipe = ''; }
592	
593	  const p = G.player;
594	  /* 换道 */
595	  if (moveLR !== 0 && p.state !== STATE_SLIDE) {
596	    p.targetLane = clamp(p.targetLane + moveLR, 0, LANE_COUNT - 1);
597	  }
598	  /* 跳跃 */
599	  if (jump && p.state === STATE_RUN) {
600	    p.state = STATE_JUMP;
601	    p.stateTimer = 28;
602	    p.jumpVel = -7;
603	  }
604	  /* 滑铲 */
605	  if (slide && p.state === STATE_RUN) {
606	    p.state = STATE_SLIDE;
607	    p.stateTimer = 22;
608	  }
609	
610	  /* 消耗一次性按键 */
611	  G.keys['ArrowUp'] = false; G.keys['w'] = false; G.keys['W'] = false;
612	  G.keys['ArrowDown'] = false; G.keys['s'] = false; G.keys['S'] = false;
613	}
614	
615	/* =========================== 游戏更新 =========================== */
616	function update() {
617	  if (G.state !== 'playing') return;
618	
619	  const p = G.player;
620	
621	  /* --- 速度 & 距离 --- */
622	  G.speed = Math.min(G.speed + SPEED_INC, MAX_SPEED);
623	  G.distance += G.speed * DISTANCE_PER_FRAME;
624	  G.score = Math.floor(G.distance * DISTANCE_SCORE);
625	
626	  /* --- 无敌计时 --- */
627	  if (G.invincible > 0) G.invincible--;
628	
629	  /* --- 轨道平滑切换 --- */
630	  p.lane = lerp(p.lane, p.targetLane, 0.25);
631	
632	  /* --- 玩家状态 --- */
633	  if (p.state === STATE_JUMP) {
634	    p.stateTimer--;
635	    if (p.stateTimer <= 0) {
636	      p.state = STATE_RUN;
637	      p.stateTimer = 0;
638	    }
639	  } else if (p.state === STATE_SLIDE) {
640	    p.stateTimer--;
641	    if (p.stateTimer <= 0) {
642	      p.state = STATE_RUN;
643	      p.stateTimer = 0;
644	    }
645	  } else if (p.state === STATE_HIT) {
646	    p.stateTimer--;
647	    if (p.stateTimer <= 0) {
648	      p.state = STATE_RUN;
649	    }
650	  }
651	
652	  /* --- 动画帧 --- */
653	  p.animTimer++;
654	  if (p.animTimer > 8) {
655	    p.animTimer = 0;
656	    p.animFrame = (p.animFrame + 1) % 4;
657	  }
658	
659	  /* --- 移动障碍物 --- */
660	  for (let i = 0; i < G.obstacles.length; i++) {
661	    const obs = G.obstacles[i];
662	    if (!obs.active) continue;
663	    obs.dist -= G.speed;
664	    if (obs.dist < -30) { obs.active = false; continue; }
665	    /* 碰撞检测（仅当障碍物接近玩家时） */
666	    if (!obs.passed && obs.dist < 30 && obs.dist > -10) {
667	      if (sameLane(obs)) {
668	        /* 低障碍：滑铲可通过 */
669	        if (obs.type === OBS_LOW && p.state === STATE_SLIDE) continue;
670	        /* 中障碍：跳跃可通过 */
671	        if (obs.type === OBS_MID && p.state === STATE_JUMP) continue;
672	        /* 高障碍：必须换道——同轨即受伤 */
673	        hurtPlayer(1);
674	      }
675	    }
676	  }
677	
678	  /* --- 移动金币 --- */
679	  for (let i = 0; i < G.coins.length; i++) {
680	    const coin = G.coins[i];
681	    if (!coin.active) continue;
682	    coin.dist -= G.speed;
683	    if (coin.dist < -30) { coin.active = false; continue; }
684	    /* 收集检测 */
685	    if (!coin.collected && coin.dist < 25 && coin.dist > -15 && Math.abs(coin.lane - p.lane) < 0.7) {
686	      coin.collected = true;
687	      coin.sparkTimer = 10;
688	      G.score += COIN_SCORE;
689	      /* 收集粒子 */
690	      const s = worldToScreen(coin.dist);
691	      const sx = laneX(coin.lane, coin.dist);
692	      for (let j = 0; j < 6; j++) {
693	        poolGet(G.particles, () => createParticle(0,0,0,0,0,'#ff0'))
694	          .x = sx + (Math.random()-0.5)*20;
695	        const pt = G.particles[G.particles.length-1];
696	        pt.y = s.y + (Math.random()-0.5)*20;
697	        pt.vx = (Math.random()-0.5)*4;
698	        pt.vy = (Math.random()-0.5)*4 - 2;
699	        pt.life = randInt(10, 25);
700	        pt.maxLife = pt.life;
701	        pt.color = randChoice(['#ffdd44','#ffaa00','#ffe680','#fff']);
702	      }
703	    }
704	  }
705	
706	  /* --- 更新粒子 --- */
707	  for (let i = 0; i < G.particles.length; i++) {
708	    const pt = G.particles[i];
709	    if (!pt.active) continue;
710	    pt.x += pt.vx;
711	    pt.y += pt.vy;
712	    pt.life--;
713	    if (pt.life <= 0) pt.active = false;
714	  }
715	
716	  /* --- 生成障碍物 --- */
717	  G.spawnTimer++;
718	  const interval = G.spawnInterval / (G.speed / BASE_SPEED);
719	  if (G.spawnTimer >= interval) {
720	    G.spawnTimer = 0;
721	    spawnObstacle();
722	  }
723	
724	  /* --- 生成金币 --- */
725	  G.coinTimer++;
726	  if (G.coinTimer > 25 + Math.random() * 20) {
727	    G.coinTimer = 0;
728	    spawnCoinRow();
729	  }
730	
731	  /* --- 清理远处对象 --- */
732	  cleanupPool(G.obstacles);
733	  cleanupPool(G.coins);
734	  cleanupPool(G.particles);
735	
736	  /* --- 计算玩家屏幕坐标 --- */
737	  p.y = G.groundY;
738	  if (p.state === STATE_JUMP) {
739	    p.y = G.groundY - 55 - (p.stateTimer / 28) * 30;
740	  }
741	  p.scale = 1.0;
742	  p.x = laneX(p.lane, 0);
743	}
744	
745	/* =========================== 碰撞检测 =========================== */
746	function sameLane(obs) {
747	  return Math.abs(obs.lane - G.player.lane) < 0.6;
748	}
749	
750	/* =========================== 对象生成 =========================== */
751	function spawnObstacle() {
752	  /* 选择一个障碍物类型 */
753	  const speedRatio = (G.speed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED);
754	  let types;
755	  if (speedRatio < 0.2) {
756	    types = [OBS_LOW, OBS_LOW, OBS_MID];           // 早期：多低障碍
757	  } else if (speedRatio < 0.5) {
758	    types = [OBS_LOW, OBS_MID, OBS_MID, OBS_HIGH]; // 中期：引入中高障碍
759	  } else {
760	    types = [OBS_LOW, OBS_MID, OBS_HIGH, OBS_HIGH];// 后期：混合
761	  }
762	  const type = randChoice(types);
763	
764	  /* 选择轨道（避免堆叠） */
765	  const lane = randInt(0, 2);
766	
767	  /* 检查同轨道前方是否有障碍物太近 */
768	  for (let i = 0; i < G.obstacles.length; i++) {
769	    const obs = G.obstacles[i];
770	    if (obs.active && obs.lane === lane && obs.dist > G.maxDist - 100 && obs.dist < G.maxDist - 30) {
771	      return; // 太近，跳过
772	    }
773	  }
774	
775	  poolGet(G.obstacles, () => createObstacle(0, OBS_LOW, 0));
776	  const o = G.obstacles[G.obstacles.length - 1];
777	  o.lane = lane;
778	  o.type = type;
779	  o.dist = G.maxDist;
780	  o.passed = false;
781	}
782	
783	function spawnCoinRow() {
784	  /* 在一到两条轨道生成金币行 */
785	  const count = randInt(1, 3);
786	  const lanes = [];
787	  while (lanes.length < count) {
788	    const l = randInt(0, 2);
789	    if (!lanes.includes(l)) lanes.push(l);
790	  }
791	  lanes.forEach(l => {
792	    for (let d = G.maxDist - 30; d < G.maxDist + 20; d += 40) {
793	      poolGet(G.coins, () => createCoin(0, 0));
794	      const c = G.coins[G.coins.length - 1];
795	      c.lane = l;
796	      c.dist = d + Math.random() * 15;
797	      c.collected = false;
798	    }
799	  });
800	}
801	
802	function cleanupPool(pool) {
803	  /* 只清理距离很远且已失效的对象，减少 splice 操作 */
804	  /* 实际：对象池不真正删除，只标记 inactive 并在获取时复用 */
805	}
806	
807	/* =========================== 渲染 =========================== */
808	function render() {
809	  const ctx = G.ctx;
810	  ctx.clearRect(0, 0, G.W, G.H);
811	
812	  /* --- 天空 --- */
813	  ctx.drawImage(G.offscreen.sky, 0, 0);
814	
815	  /* --- 远城市场景视差 --- */
816	  const cityOffset = (G.distance * 0.15) % (G.W * 3);
817	  ctx.drawImage(G.offscreen.city, -cityOffset, G.vanishY - 30, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);
818	
819	  /* --- 近建筑视差 --- */
820	  const nearOffset = (G.distance * 0.3) % (G.W * 2);
821	  ctx.drawImage(G.offscreen.nearCity, -nearOffset, G.vanishY + 10, G.W, G.H*0.35, 0, G.vanishY + 10, G.W, G.H*0.35);
822	
823	  /* --- 地面 --- */
824	  drawGround(ctx);
825	
826	  /* --- 轨道 --- */
827	  drawTracks(ctx);
828	
829	  /* --- 收集所有需要深度排序的实体 --- */
830	  const entities = [];
831	
832	  /* 障碍物 */
833	  for (let i = 0; i < G.obstacles.length; i++) {
834	    const o = G.obstacles[i];
835	    if (!o.active) continue;
836	    entities.push({ type:'obstacle', obj:o, dist:o.dist, lane:o.lane });
837	  }
838	
839	  /* 金币 */
840	  for (let i = 0; i < G.coins.length; i++) {
841	    const c = G.coins[i];
842	    if (!c.active || c.collected) continue;
843	    entities.push({ type:'coin', obj:c, dist:c.dist, lane:c.lane });
844	  }
845	
846	  /* 按距离排序（远处先画） */
847	  entities.sort((a, b) => b.dist - a.dist);
848	
849	  /* --- 绘制所有实体 --- */
850	  entities.forEach(e => {
851	    const s = worldToScreen(e.dist);
852	    if (s.y < G.vanishY - 20 || s.y > G.H + 20) return;
853	    const sx = laneX(e.lane, e.dist);
854	
855	    if (e.type === 'obstacle') {
856	      drawObstacle(ctx, e.obj, sx, s.y, s.scale);
857	    } else if (e.type === 'coin') {
858	      drawCoin(ctx, e.obj, sx, s.y, s.scale);
859	    }
860	  });
861	
862	  /* --- 玩家 --- */
863	  drawPlayer(ctx);
864	
865	  /* --- 粒子（玩家上方） --- */
866	  for (let i = 0; i < G.particles.length; i++) {
867	    const p = G.particles[i];
868	    if (!p.active) continue;
869	    const alpha = p.life / p.maxLife;
870	    ctx.globalAlpha = alpha;
871	    ctx.fillStyle = p.color;
872	    ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
873	  }
874	  ctx.globalAlpha = 1;
875	
876	  /* --- HUD --- */
877	  drawHUD(ctx);
878	
879	  /* --- 界面状态 --- */
880	  if (G.state === 'start') drawStartScreen(ctx);
881	  if (G.state === 'dead') drawDeathScreen(ctx);
882	}
883	
884	/* =========================== 绘制地面 =========================== */
885	function drawGround(ctx) {
886	  /* 地面区域：从消失点下方到屏幕底 */
887	  const groundTop = G.vanishY + 30;
888	  const groundBot = G.H;
889	
890	  /* 碎石地表渐变 */
891	  const grad = ctx.createLinearGradient(0, groundTop, 0, groundBot);
892	  grad.addColorStop(0, '#8b7355');
893	  grad.addColorStop(0.3, '#9b8b75');
894	  grad.addColorStop(0.7, '#a09080');
895	  grad.addColorStop(1, '#b0a090');
896	  ctx.fillStyle = grad;
897	  ctx.fillRect(0, groundTop, G.W, groundBot - groundTop);
898	
899	  /* 碎石纹理点 */
900	  ctx.fillStyle = 'rgba(120,110,100,0.3)';
901	  const seed = 42; // 固定种子保持稳定
902	  for (let y = groundTop; y < groundBot; y += 12) {
903	    for (let x = 0; x < G.W; x += 14) {
904	      if (((x * 31 + y * 17 + seed) % 7) === 0) {
905	        ctx.fillRect(x, y, 2, 2);
906	      }
907	    }
908	  }
909	}
910	
911	/* =========================== 绘制轨道 =========================== */
912	function drawTracks(ctx) {
913	  for (let lane = 0; lane < LANE_COUNT; lane++) {
914	    /* 钢轨 */
915	    const railWidth = 5;
916	
917	    /* 左轨 */
918	    ctx.strokeStyle = '#8899aa';
919	    ctx.lineWidth = railWidth;
920	    ctx.beginPath();
921	    for (let d = 0; d <= G.maxDist; d += 20) {
922	      const s = worldToScreen(d);
923	      const lx = laneX(lane, d) - 8;
924	      if (d === 0) ctx.moveTo(lx, s.y);
925	      else ctx.lineTo(lx, s.y);
926	    }
927	    ctx.stroke();
928	
929	    /* 右轨 */
930	    ctx.beginPath();
931	    for (let d = 0; d <= G.maxDist; d += 20) {
932	      const s = worldToScreen(d);
933	      const rx = laneX(lane, d) + 8;
934	      if (d === 0) ctx.moveTo(rx, s.y);
935	      else ctx.lineTo(rx, s.y);
936	    }
