function drawPlayerSprite(ctx, state, w, h) {
  ctx.clearRect(0, 0, w, h);
  const cx = w/2, cy = h * 0.55;

  /* 阴影（在所有姿态下） */
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.beginPath();
  ctx.ellipse(cx, cy+14, 16, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  if (state === STATE_SLIDE) {
    /* === 滑铲：俯身贴地 === */
    /* 身体横向延展 */
    ctx.fillStyle = '#e94560';
    ctx.beginPath(); ctx.roundRect(cx-24, cy-10, 48, 20, 6); ctx.fill();
    /* 连帽衫细节--中心拉链线 */
    ctx.strokeStyle = '#c23152';
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(cx-6, cy-10); ctx.lineTo(cx-6, cy+10); ctx.stroke();
    /* 帽子（后脑） */
    ctx.fillStyle = '#c23152';
    ctx.beginPath(); ctx.arc(cx-16, cy-4, 9, 0, Math.PI*2); ctx.fill();
    /* 护目镜 */
    ctx.fillStyle = '#88ccff';
    ctx.beginPath(); ctx.arc(cx-20, cy-6, 4, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(cx-21, cy-7, 1.5, 0, Math.PI*2); ctx.fill();
    /* 腿（向后延伸） */
    ctx.fillStyle = '#2d2d44';
    ctx.fillRect(cx-8, cy+6, 32, 10);
    ctx.fillStyle = '#e94560';
    ctx.fillRect(cx+16, cy+8, 16, 6);
    /* 运动鞋 */
    ctx.fillStyle = '#f0f0f0';
    ctx.beginPath(); ctx.roundRect(cx+26, cy+7, 12, 7, 2); ctx.fill();
    ctx.fillStyle = '#333';
    ctx.fillRect(cx+28, cy+7, 8, 2);
    /* 前伸手臂 */
    ctx.fillStyle = '#e94560';
    ctx.fillRect(cx-32, cy-4, 14, 7);
    ctx.fillStyle = '#ffd3b6';
    ctx.beginPath(); ctx.arc(cx-34, cy-2, 4, 0, Math.PI*2); ctx.fill();
  } else if (state === STATE_JUMP) {
    /* === 跳跃：身体蜷缩、向上 === */
    /* 腿（蜷起） */
    ctx.fillStyle = '#2d2d44';
    ctx.fillRect(cx-12, cy+4, 10, 16); ctx.fillRect(cx+4, cy+4, 10, 16);
    ctx.fillStyle = '#e94560';
    ctx.fillRect(cx-10, cy+2, 14, 20);
    /* 鞋（上翘） */
    ctx.fillStyle = '#f0f0f0';
    ctx.beginPath(); ctx.roundRect(cx-13, cy+18, 12, 6, 2); ctx.fill();
    ctx.beginPath(); ctx.roundRect(cx+3, cy+18, 12, 6, 2); ctx.fill();
    /* 身体抬起 */
    ctx.fillStyle = '#e94560';
    ctx.beginPath(); ctx.roundRect(cx-14, cy-32, 28, 36, 7); ctx.fill();
    /* 帽子 */
    ctx.fillStyle = '#c23152';
    ctx.beginPath(); ctx.arc(cx, cy-40, 12, Math.PI, 0); ctx.fill();
    /* 脸 */
    ctx.fillStyle = '#ffd3b6';
    ctx.beginPath(); ctx.arc(cx, cy-36, 8, 0, Math.PI*2); ctx.fill();
    /* 护目镜 */
    ctx.fillStyle = '#88ccff';
    ctx.beginPath(); ctx.arc(cx, cy-38, 4.5, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(cx-1, cy-40, 1.5, 0, Math.PI*2); ctx.fill();
    /* 手臂（上摆） */
    ctx.fillStyle = '#e94560';
    ctx.fillRect(cx-22, cy-28, 9, 20);
    ctx.fillStyle = '#ffd3b6';
    ctx.beginPath(); ctx.arc(cx-18, cy-32, 5, 0, Math.PI*2); ctx.fill();
  } else if (state === STATE_HIT) {
    /* === 受击：后仰、红色 === */
    /* 腿 */
    ctx.fillStyle = '#2d2d44';
    ctx.fillRect(cx-10, cy+6, 8, 18); ctx.fillRect(cx+4, cy+6, 8, 16);
    ctx.fillStyle = '#f0f0f0';
    ctx.fillRect(cx-11, cy+20, 10, 6); ctx.fillRect(cx+3, cy+20, 10, 6);
    /* 身体（后倾、红色调） */
    ctx.fillStyle = '#ff4444';
    ctx.beginPath(); ctx.roundRect(cx-10, cy-28, 20, 32, 6); ctx.fill();
    /* 头 */
    ctx.fillStyle = '#cc0000';
    ctx.beginPath(); ctx.arc(cx, cy-36, 10, 0, Math.PI*2); ctx.fill();
    /* X眼 */
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(cx-4, cy-38); ctx.lineTo(cx-1, cy-35); ctx.moveTo(cx-1, cy-38); ctx.lineTo(cx-4, cy-35); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx+2, cy-38); ctx.lineTo(cx+5, cy-35); ctx.moveTo(cx+5, cy-38); ctx.lineTo(cx+2, cy-35); ctx.stroke();
  } else {
    /* === 奔跑：动态姿态 === */
    /* 后腿 */
    ctx.fillStyle = '#2d2d44';
    ctx.fillRect(cx-12, cy+4, 8, 16);
    ctx.fillStyle = '#f0f0f0';
    ctx.beginPath(); ctx.roundRect(cx-13, cy+18, 10, 6, 2); ctx.fill();
    /* 身体/连帽衫 */
    ctx.fillStyle = '#e94560';
    ctx.beginPath(); ctx.roundRect(cx-12, cy-30, 24, 34, 7); ctx.fill();
    /* 连帽衫拉链 */
    ctx.strokeStyle = '#c23152';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(cx, cy-30); ctx.lineTo(cx, cy+4); ctx.stroke();
    /* 帽子（披在背后） */
    ctx.fillStyle = '#c23152';
    ctx.beginPath();
    ctx.moveTo(cx-12, cy-30);
    ctx.quadraticCurveTo(cx-20, cy-18, cx-8, cy);
    ctx.quadraticCurveTo(cx, cy-12, cx-2, cy-30);
    ctx.fill();
    /* 头部 */
    ctx.fillStyle = '#ffd3b6';
    ctx.beginPath(); ctx.arc(cx, cy-36, 9, 0, Math.PI*2); ctx.fill();
    /* 头发 */
    ctx.fillStyle = '#2a1a0a';
    ctx.beginPath(); ctx.arc(cx, cy-40, 9, Math.PI, 0); ctx.fill();
    /* 护目镜 */
    ctx.fillStyle = '#88ccff';
    ctx.beginPath(); ctx.arc(cx, cy-37, 5, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(cx-1.5, cy-39, 2, 0, Math.PI*2); ctx.fill();
    /* 前腿 */
    ctx.fillStyle = '#2d2d44';
    ctx.fillRect(cx+4, cy+2, 8, 18);
    ctx.fillStyle = '#f0f0f0';
    ctx.beginPath(); ctx.roundRect(cx+3, cy+18, 10, 6, 2); ctx.fill();
    /* 鞋底 */
    ctx.fillStyle = '#555';
    ctx.fillRect(cx+3, cy+22, 10, 2);
    /* 手臂（摆动） */
    ctx.fillStyle = '#ffd3b6';
    ctx.fillRect(cx-18, cy-20, 6, 14); ctx.fillRect(cx+14, cy-24, 6, 14);
    /* 手套 */
    ctx.fillStyle = '#333';
    ctx.fillRect(cx-19, cy-8, 8, 4); ctx.fillRect(cx+13, cy-12, 8, 4);
  }
}

