1794	function roundRect(ctx, x, y, w, h, r) {
1795	  ctx.beginPath();
1796	  ctx.moveTo(x + r, y);
1797	  ctx.lineTo(x + w - r, y);
1798	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
1799	  ctx.lineTo(x + w, y + h - r);
1800	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
1801	  ctx.lineTo(x + r, y + h);
1802	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
1803	  ctx.lineTo(x, y + r);
1804	  ctx.quadraticCurveTo(x, y, x + r, y);
1805	  ctx.closePath();
