1817	    G.fps = G.frameCount;
1818	    G.frameCount = 0;
1819	    G.fpsTime = 0;
1820	  }
1821	
1822	  processInput();
1823	  update();
1824	  render();
1825	  requestAnimationFrame(gameLoop);
1826	}
