1811	  G.lastTime = timestamp;
1812	
1813	  /* FPS 计算 */
1814	  G.frameCount++;
1815	  G.fpsTime += G.deltaTime;
1816	  if (G.fpsTime >= 1000) {
1817	    G.fps = G.frameCount;
1818	    G.frameCount = 0;
1819	    G.fpsTime = 0;
1820	  }
1821	
1822	  processInput();
1823	  update();
1824	  render();
1825	  requestAnimationFrame(gameLoop);
