      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(1, -2, 1.2, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    } else if (p.celebrateType === 'kick') {
      /* 踢腿——一条腿向前踢出 */
