/* =========================== 角色动画系统 =========================== */
/* 角色颜色 */
const C_SKIN = '#ffd3b6';
const C_HAIR = '#2a1a0a';
const C_HOODIE = '#e94560';
const C_HOODIE_DARK = '#c23152';
const C_PANTS = '#2d2d44';
const C_SHOE = '#f0f0f0';
const C_SOLE = '#333';
const C_GOGGLE = '#88ccff';
const C_GOGGLE_FRAME = '#555';
const C_EYE = '#fff';

/* 绘制圆角矩形（路径） */
function rr(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

/* 绘制肢体段 */
function limb(ctx, x1, y1, x2, y2, thickness, color) {
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.sqrt(dx*dx + dy*dy);
  const angle = Math.atan2(dy, dx);
  ctx.save();
  ctx.translate(x1, y1);
  ctx.rotate(angle);
  ctx.fillStyle = color;
  rr(ctx, 0, -thickness/2, len, thickness, thickness/2);
  ctx.fill();
  ctx.restore();
}

/* 绘制关节球 */
function joint(ctx, x, y, r, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
}

/* ========== 各状态姿态计算 ========== */
function getRunPose(phase) {
  // phase: 0-1 running cycle
  const a = phase * Math.PI * 2;
  return {
    bodyY: Math.abs(Math.sin(a)) * 4,
    bodyLean: 0.08,
    // Left side (background)
    lThigh: Math.sin(a) * 0.7,
    lCalf: Math.max(0, Math.sin(a)) * 0.9,
    lUpperArm: Math.sin(a + Math.PI) * 0.55,
    lForearm: Math.max(0, Math.sin(a + Math.PI)) * 0.6,
    // Right side (foreground) - opposite phase
    rThigh: Math.sin(a + Math.PI) * 0.7,
    rCalf: Math.max(0, Math.sin(a + Math.PI)) * 0.9,
    rUpperArm: Math.sin(a) * 0.55,
    rForearm: Math.max(0, Math.sin(a)) * 0.6,
    headTilt: Math.sin(a) * 0.05,
  };
}

// ... etc for other states

/* ========== 主绘制函数 ========== */
function drawCharacter(ctx, x, y, state, frameCount, celebrateType, celebrateTimer, alpha) {
  ctx.save();
  ctx.translate(x, y);
  if (alpha !== undefined) ctx.globalAlpha = alpha;

  const phase = (frameCount * 0.15) % 1;
  let pose;

  if (state === STATE_RUN && celebrateType) {
    // Blend celebration with run pose
    pose = getCelebratePose(celebrateType, celebrateTimer);
  } else if (state === STATE_RUN) {
    pose = getRunPose(phase);
  } else if (state === STATE_JUMP) {
    pose = getJumpPose(...);
  } // etc

  // Draw in order: back arm, back leg, torso, head, front leg, front arm
  drawBackArm(ctx, pose);
  drawBackLeg(ctx, pose);
  drawTorso(ctx, pose);
  drawHead(ctx, pose, celebrateType);
  drawFrontLeg(ctx, pose);
  drawFrontArm(ctx, pose);

  ctx.restore();
}
