function drawPlayer(ctx) {
  const p = G.player;
  ctx.save();
  ctx.translate(p.x, p.y);

  /* 无敌闪烁 */
  if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
    ctx.globalAlpha = 0.4;
  }

  /* 奔跑时的上下起伏 */
  let bounceY = 0;
  if (p.state === STATE_RUN) {
    bounceY = Math.sin(G.frameCount * 0.4) * 2;
  }

  /* 阴影 */
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.beginPath();
  ctx.ellipse(0, 14, 18, 6, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.translate(0, bounceY);

  const sprite = G.offscreen.player[p.state];
  if (sprite) {
    ctx.drawImage(sprite, -sprite.width/2, -sprite.height/2 + 8);
  }

  /* 庆祝动作 */
  if (p.celebrateTimer > 0 && p.state === STATE_RUN) {
    const progress = 1 - (p.celebrateTimer / (p.celebrateType === 'lookback' ? 40 : 35));
    if (p.celebrateType === 'lookback') {
      /* 回头——头部转向侧后方 */
      const lookAngle = Math.sin(progress * Math.PI) * 0.5; // 左右摆动
      ctx.save();
      ctx.translate(8, -26);
      ctx.rotate(lookAngle);
      ctx.fillStyle = '#ffd3b6';
      ctx.beginPath(); ctx.arc(0, 0, 7, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#88ccff';
      ctx.beginPath(); ctx.arc(2, -1, 3.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(1, -2, 1.2, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    } else if (p.celebrateType === 'kick') {
      /* 踢腿——一条腿向前踢出 */
      const kickAngle = -Math.sin(progress * Math.PI) * 0.8; // 踢腿弧度
      ctx.save();
      ctx.translate(10, 12);
      ctx.rotate(kickAngle);
      ctx.fillStyle = '#2d2d44';
      ctx.fillRect(0, -4, 22, 8);
      ctx.fillStyle = '#f0f0f0';
      ctx.fillRect(18, -4, 10, 8); // 鞋子
      ctx.restore();
    }
  }

  ctx.restore();
}

