   ======================================================================== */

/* ---- 角色配色 ---- */
const CC = {
  skin:    '#ffd3b6',
  skinShadow:'#e8bfa5',
  hair:    '#2a1a0a',
  hairHighlight:'#3d2818',
  hoodie:  '#e94560',
  hoodieInner:'#c23152',
  hoodieFold:'#d63852',
  pants:   '#2d2d44',
  pantsFold:'#252538',
  shoe:    '#f0f0f0',
  shoeSole:'#333',
  shoeAccent:'#e94560',
  goggleLens:'#88ccff',
  goggleFrame:'#555',
  goggleHighlight:'rgba(255,255,255,0.4)',
  eye:     '#fff',
  pupil:   '#1a1a1a',
  mouth:   '#c44',
};

/* ---- 角色尺寸常量 ---- */
const CH = {
  headW: 11, headH: 12,
  neckLen: 3,
  torsoW: 16, torsoH: 26,
  hipW: 13,
  upperArmW: 6, upperArmL: 16,
  forearmW: 5, forearmL: 14,
  handR: 4.5,
  thighW: 7, thighL: 20,
  calfW: 6, calfL: 18,
  footW: 6, footL: 11,
  shoulderX: 9,  // 肩距中心
  hipX: 7,
};

/* ---- 辅助：画肢体段（从 (x1,y1) 到 (x2,y2)，带厚度和颜色） ---- */
function drawSegment(ctx, x1, y1, x2, y2, thick, color, shadowColor) {
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.sqrt(dx * dx + dy * dy);
  if (len < 0.5) return;
  const angle = Math.atan2(dy, dx);
  ctx.save();
  ctx.translate(x1, y1);
  ctx.rotate(angle);
  // 主体矩形
  ctx.fillStyle = color;
  ctx.fillRect(0, -thick / 2, len, thick);
  // 暗面
  if (shadowColor) {
    ctx.fillStyle = shadowColor;
    ctx.fillRect(0, 0, len, thick / 2);
  }
  ctx.restore();
}

/* ---- 辅助：关节球 ---- */
function drawJoint(ctx, x, y, r, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
}

/* ---- 辅助：椭圆 ---- */
function drawEllipse(ctx, x, y, rx, ry, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); ctx.fill();
}

/* ---- 辅助：鞋 ---- */
function drawShoe(ctx, x, y, angle, scaleX) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.scale(scaleX || 1, 1);
  // 鞋身
  ctx.fillStyle = CC.shoe;
  ctx.beginPath();
  ctx.moveTo(-4, -2);
  ctx.lineTo(CH.footL - 2, -2);
  ctx.quadraticCurveTo(CH.footL + 2, 0, CH.footL - 2, 3);
  ctx.lineTo(-2, 3);
  ctx.quadraticCurveTo(-5, 0, -4, -2);
  ctx.fill();
  // 鞋底
  ctx.fillStyle = CC.shoeSole;
  ctx.fillRect(-2, 1, CH.footL + 2, 3);
  // 装饰线
  ctx.strokeStyle = CC.shoeAccent;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(1, -1); ctx.lineTo(1, 4); ctx.stroke();
  ctx.restore();
}

/* ---- 辅助：手 ---- */
function drawHand(ctx, x, y, color) {
  ctx.fillStyle = color || CC.skin;
  ctx.beginPath(); ctx.arc(x, y, CH.handR, 0, Math.PI * 2); ctx.fill();
  // 手指关节线
  ctx.strokeStyle = CC.skinShadow;
  ctx.lineWidth = 0.6;
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(x + i * 1.5, y - 2);
    ctx.lineTo(x + i * 1.5, y + 1);
    ctx.stroke();
  }
}

/* ---- 辅助：头 ---- */
function drawHead(ctx, x, y, tilt, facingRight, expression) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(tilt || 0);

  // 脖子
  ctx.fillStyle = CC.skinShadow;
  ctx.fillRect(-3, CH.neckLen - 2, 6, 5);

  // 头——略扁的椭圆
  drawEllipse(ctx, 0, -CH.headH / 2 + 4, CH.headW, CH.headH, CC.skin);

  // 头发——顶部和后方
  ctx.fillStyle = CC.hair;
  ctx.beginPath();
  ctx.arc(0, -CH.headH + 5, CH.headW + 2, Math.PI, 2 * Math.PI);
  ctx.fill();
  // 刘海
  ctx.beginPath();
  ctx.moveTo(-CH.headW, -CH.headH + 6);
  ctx.quadraticCurveTo(-6, -CH.headH, 2, -CH.headH + 2);
  ctx.quadraticCurveTo(8, -CH.headH + 4, CH.headW - 1, -CH.headH + 8);
  ctx.lineTo(CH.headW, -CH.headH + 3);
  ctx.quadraticCurveTo(4, -CH.headH - 1, -CH.headW, -CH.headH + 3);
  ctx.fill();
  // 高光
  ctx.fillStyle = CC.hairHighlight;
  ctx.beginPath();
  ctx.arc(-3, -CH.headH + 3, 4, 0, Math.PI * 2);
  ctx.fill();

  // 面部（3/4侧脸的可见部分）
  if (facingRight) {
    // 右脸颊可见更多
    drawEllipse(ctx, 4, -CH.headH / 2 - 2, 4, 7, CC.skin);
    // 眼睛
    ctx.fillStyle = CC.eye;
    ctx.beginPath(); ctx.arc(3, -CH.headH / 2 - 5, 2.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = CC.pupil;
    ctx.beginPath(); ctx.arc(4, -CH.headH / 2 - 5, 1.3, 0, Math.PI * 2); ctx.fill();
    // 眉毛
    ctx.strokeStyle = CC.hair;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(1, -CH.headH / 2 - 8); ctx.lineTo(6, -CH.headH / 2 - 8); ctx.stroke();
  } else {
    // 左眼
    ctx.fillStyle = CC.eye;
    ctx.beginPath(); ctx.arc(-3, -CH.headH / 2 - 5, 2.2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = CC.pupil;
    ctx.beginPath(); ctx.arc(-2, -CH.headH / 2 - 5, 1.2, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = CC.hair;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-6, -CH.headH / 2 - 8); ctx.lineTo(-1, -CH.headH / 2 - 8); ctx.stroke();
  }

  // 嘴
  if (expression === 'hurt') {
    ctx.strokeStyle = CC.mouth;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, -CH.headH / 2 + 1, 3.5, 0.3, Math.PI - 0.3); ctx.stroke();
  } else if (expression === 'happy') {
    ctx.strokeStyle = CC.mouth;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, -CH.headH / 2, 2.5, 0.1, Math.PI - 0.1); ctx.stroke();
  }

  // 护目镜（戴在额头或眼睛上）
  const goggleY = -CH.headH + 1;
  ctx.fillStyle = CC.goggleFrame;
  ctx.beginPath();
  ctx.arc(-4, goggleY, 5, 0, Math.PI * 2);
  ctx.arc(4, goggleY, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = CC.goggleLens;
  ctx.beginPath();
  ctx.arc(-4, goggleY, 3.8, 0, Math.PI * 2);
  ctx.arc(4, goggleY, 3.8, 0, Math.PI * 2);
  ctx.fill();
  // 镜片高光
  ctx.fillStyle = CC.goggleHighlight;
  ctx.beginPath(); ctx.arc(-5, goggleY - 1, 1.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(3, goggleY - 1, 1.5, 0, Math.PI * 2); ctx.fill();
  // 连接桥
  ctx.strokeStyle = CC.goggleFrame;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(0, goggleY); ctx.lineTo(0, goggleY); ctx.stroke();

  // 耳朵
  ctx.fillStyle = CC.skin;
  ctx.beginPath(); ctx.arc(-CH.headW + 1, -CH.headH / 2 - 1, 3, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}

/* ---- 辅助：躯干（连帽衫） ---- */
function drawTorsoBody(ctx, ox, oy, lean, bounce) {
  ctx.save();
  ctx.translate(ox, oy + (bounce || 0));
  ctx.rotate(lean || 0);

  // 骨盆
  ctx.fillStyle = CC.pants;
  ctx.beginPath();
  ctx.moveTo(-CH.hipX, -4);
  ctx.lineTo(CH.hipX, -4);
  ctx.lineTo(CH.hipX + 2, 5);
  ctx.lineTo(-CH.hipX - 2, 5);
  ctx.closePath();
  ctx.fill();
  // 腰带
  ctx.fillStyle = CC.hoodieInner;
  ctx.fillRect(-CH.hipX - 2, -4, CH.hipX * 2 + 4, 3);

  // 躯干（连帽衫）
  const tx = -CH.torsoW / 2;
  const ty = -CH.torsoH;
  ctx.fillStyle = CC.hoodie;
  ctx.beginPath();
  ctx.moveTo(tx + 3, ty + 5);
  ctx.lineTo(tx, ty + CH.torsoH * 0.3);
  ctx.lineTo(tx - 1, 0);
  ctx.lineTo(tx + CH.torsoW + 1, 0);
  ctx.lineTo(tx + CH.torsoW, ty + CH.torsoH * 0.3);
  ctx.lineTo(tx + CH.torsoW - 3, ty + 5);
  ctx.closePath();
  ctx.fill();

  // 连帽衫褶皱
  ctx.strokeStyle = CC.hoodieFold;
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    const fy = ty + CH.torsoH * 0.25 + i * 8;
    ctx.beginPath();
    ctx.moveTo(tx + 4, fy);
    ctx.quadraticCurveTo(tx + CH.torsoW / 2, fy + (i % 2) * 3, tx + CH.torsoW - 4, fy);
    ctx.stroke();
  }
  // 中心拉链
  ctx.strokeStyle = CC.hoodieInner;
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(0, ty + 4); ctx.lineTo(0, 0); ctx.stroke();

  // 兜帽（垂在背后）
  ctx.fillStyle = CC.hoodieInner;
  ctx.beginPath();
  ctx.moveTo(tx, ty + 5);
  ctx.quadraticCurveTo(tx - 6, ty - 8, tx + 2, ty - 4);
  ctx.quadraticCurveTo(tx + CH.torsoW / 2, ty - 14, tx + CH.torsoW - 2, ty - 4);
  ctx.quadraticCurveTo(tx + CH.torsoW + 6, ty - 8, tx + CH.torsoW, ty + 5);
  ctx.fill();
  // 兜帽内衬
  ctx.fillStyle = CC.hoodieFold;
  ctx.beginPath();
  ctx.arc(0, ty - 6, CH.torsoW * 0.55, 0, Math.PI);
  ctx.fill();

  ctx.restore();

  // 返回肩部位置（用于连接手臂和头部）
  return {
    shoulderLY: oy - CH.torsoH * 0.7 + (bounce || 0),
    shoulderRY: oy - CH.torsoH * 0.7 + (bounce || 0),
    shoulderLX: ox - CH.shoulderX,
    shoulderRX: ox + CH.shoulderX,
    headBaseY: oy - CH.torsoH * 0.85 + (bounce || 0),
    headBaseX: ox,
    hipY: oy + (bounce || 0),
    hipX: ox,
  };
}

/* ========== 姿态计算 ========== */

function poseRun(frameCount) {
  const a = (frameCount * 0.15) % 1 * Math.PI * 2;
  return {
    bodyBounce: Math.abs(Math.sin(a)) * 5,
    bodyLean: 0.06,
    // 左腿（后/远）
    lThigh:  Math.sin(a) * 0.75,
    lCalf:   Math.max(0.1, Math.sin(a)) * 0.85,
    lFoot:   Math.max(0, Math.sin(a)) * 0.4,
    // 右腿（前/近）
    rThigh:  Math.sin(a + Math.PI) * 0.75,
    rCalf:   Math.max(0.1, Math.sin(a + Math.PI)) * 0.85,
    rFoot:   Math.max(0, Math.sin(a + Math.PI)) * 0.4,
    // 左臂（与右腿同相——自然摆臂）
    lUpper:  Math.sin(a) * 0.55,
    lFore:   Math.max(0.05, Math.sin(a)) * 0.55,
    // 右臂（与左腿同相）
    rUpper:  Math.sin(a + Math.PI) * 0.55,
    rFore:   Math.max(0.05, Math.sin(a + Math.PI)) * 0.55,
    headTilt: Math.sin(a) * 0.04,
    facingRight: true,
    expression: null,
  };
}

function poseJump(timer, total) {
  const p = 1 - timer / total; // 0(落地) → 1(起跳)
  const crouch = Math.sin(p * Math.PI); // 0 → 1 → 0 抛物线
  return {
    bodyBounce: 0,
    bodyLean: 0.15,
    lThigh:  -1.2 + crouch * 0.3,
    lCalf:   -0.9 + crouch * 0.2,
    lFoot:   0.2,
    rThigh:  -1.2 + crouch * 0.3,
    rCalf:   -0.9 + crouch * 0.2,
    rFoot:   0.2,
    lUpper:  -1.4 + crouch * 0.2,
    lFore:   -0.7 + crouch * 0.1,
    rUpper:  -1.4 + crouch * 0.2,
    rFore:   -0.7 + crouch * 0.1,
    headTilt: 0.1,
    facingRight: true,
    expression: null,
  };
}

function poseSlide(timer, total) {
  const p = timer / total; // 0(开始) → 1(结束)
  return {
    bodyBounce: -18,
    bodyLean: -0.6,
    lThigh:  0.3,
    lCalf:   1.2,
    lFoot:   0.7,
    rThigh:  -0.5,
    rCalf:   0.4,
    rFoot:   0.1,
    lUpper:  0.5,
    lFore:   0.6,
    rUpper:  0.6,
    rFore:   0.5,
    headTilt: 0.2,
    facingRight: true,
    expression: null,
  };
}

function poseHit(frameCount) {
  return {
    bodyBounce: -4,
    bodyLean: -0.25,
    lThigh:  -0.2,
    lCalf:   0.1,
    lFoot:   0,
    rThigh:  -0.3,
    rCalf:   0.2,
    rFoot:   0,
    lUpper:  -1.8,
    lFore:   -0.9,
    rUpper:  -1.6,
    rFore:   -0.8,
    headTilt: -0.3,
    facingRight: true,
    expression: 'hurt',
  };
}

function poseCelebrate(type, timer, baseTimer) {
  const p = 1 - timer / baseTimer;
  const s = Math.sin(p * Math.PI);
  if (type === 'lookback') {
    return {
      bodyBounce: 0,
      bodyLean: -0.1,
      lThigh: -0.1, lCalf: 0.1, lFoot: 0,
      rThigh: -0.1, rCalf: 0.1, rFoot: 0,
      lUpper: 0.1, lFore: 0.1,
      rUpper: -0.3, rFore: 0.2,
      headTilt: -0.6 * s, // 明显转头
      facingRight: false, // 回头看 = 露出左脸
      expression: 'happy',
      bodyTwist: 0.3 * s,
    };
  } else if (type === 'kick') {
    return {
      bodyBounce: 0,
      bodyLean: -0.15,
      lThigh: -0.1, lCalf: 0.1, lFoot: 0,
      rThigh: -1.0 * s,   // 右腿高踢
      rCalf: 0.1,
      rFoot: -0.2,
      lUpper: -0.3, lFore: 0.3,
      rUpper: 0.4, rFore: 0.2,
      headTilt: 0,
      facingRight: true,
      expression: 'happy',
      bodyTwist: 0,
    };
  }
  return poseRun(0);
}

/* ========== 主绘制：完整角色 ========== */
function drawCharacter(ctx, x, y, state, frameCount, celebrateType, celebrateTimer) {
  ctx.save();
  ctx.translate(x, y);

  let pose;
  if (state === STATE_RUN) {
    if (celebrateTimer > 0 && celebrateType) {
      const baseTimer = celebrateType === 'lookback' ? 40 : 35;
      pose = poseCelebrate(celebrateType, celebrateTimer, baseTimer);
    } else {
      pose = poseRun(frameCount);
    }
  } else if (state === STATE_JUMP) {
    pose = poseJump(G.player.stateTimer, 150);
  } else if (state === STATE_SLIDE) {
    pose = poseSlide(G.player.stateTimer, 100);
  } else if (state === STATE_HIT) {
    pose = poseHit(frameCount);
  } else {
    pose = poseRun(frameCount);
  }

  const hipOY = -12;
  const joints = drawTorsoBody(ctx, 0, hipOY, pose.bodyLean + (pose.bodyTwist || 0), pose.bodyBounce);

  // ---- 左臂（背景层） ----
  const lsx = joints.shoulderLX, lsy = joints.shoulderLY;
  const lelx = lsx + Math.sin(pose.lUpper) * CH.upperArmL;
  const lely = lsy + Math.cos(pose.lUpper) * CH.upperArmL;
  drawSegment(ctx, lsx, lsy, lelx, lely, CH.upperArmW, CC.hoodie, CC.hoodieFold);
  drawJoint(ctx, lelx, lely, 3.5, CC.hoodieInner);
  const lwx = lelx + Math.sin(pose.lUpper + pose.lFore) * CH.forearmL;
  const lwy = lely + Math.cos(pose.lUpper + pose.lFore) * CH.forearmL;
  drawSegment(ctx, lelx, lely, lwx, lwy, CH.forearmW, CC.skin, CC.skinShadow);
  drawHand(ctx, lwx, lwy, CC.skin);

  // ---- 左腿（背景层） ----
  const lhipX = joints.hipX - CH.hipX * 0.5, lhipY = joints.hipY;
  const lknex = lhipX + Math.sin(pose.lThigh) * CH.thighL;
  const lkney = lhipY + Math.cos(pose.lThigh) * CH.thighL;
  drawSegment(ctx, lhipX, lhipY, lknex, lkney, CH.thighW, CC.pants, CC.pantsFold);
  drawJoint(ctx, lknex, lkney, 3.5, CC.pantsFold);
  const lankx = lknex + Math.sin(pose.lThigh + pose.lCalf) * CH.calfL;
  const lanky = lkney + Math.cos(pose.lThigh + pose.lCalf) * CH.calfL;
  drawSegment(ctx, lknex, lkney, lankx, lanky, CH.calfW, CC.pants, CC.pantsFold);
  const lfootAngle = pose.lThigh + pose.lCalf + pose.lFoot;
  drawShoe(ctx, lankx, lanky, lfootAngle, 1);

  // ---- 右腿（前景层） ----
  const rhipX = joints.hipX + CH.hipX * 0.5, rhipY = joints.hipY;
  const rknex = rhipX + Math.sin(pose.rThigh) * CH.thighL;
  const rkney = rhipY + Math.cos(pose.rThigh) * CH.thighL;
  drawSegment(ctx, rhipX, rhipY, rknex, rkney, CH.thighW, CC.pants, CC.pantsFold);
  drawJoint(ctx, rknex, rkney, 3.5, CC.pantsFold);
  const rankx = rknex + Math.sin(pose.rThigh + pose.rCalf) * CH.calfL;
  const ranky = rkney + Math.cos(pose.rThigh + pose.rCalf) * CH.calfL;
  drawSegment(ctx, rknex, rkney, rankx, ranky, CH.calfW, CC.pants, CC.pantsFold);
  const rfootAngle = pose.rThigh + pose.rCalf + pose.rFoot;
  drawShoe(ctx, rankx, ranky, rfootAngle, 1);

  // ---- 头部 ----
  drawHead(ctx, joints.headBaseX, joints.headBaseY, pose.headTilt, pose.facingRight, pose.expression);

  // ---- 右臂（前景层） ----
  const rsx = joints.shoulderRX, rsy = joints.shoulderRY;
  const relx = rsx + Math.sin(pose.rUpper) * CH.upperArmL;
  const rely = rsy + Math.cos(pose.rUpper) * CH.upperArmL;
  drawSegment(ctx, rsx, rsy, relx, rely, CH.upperArmW, CC.hoodie, CC.hoodieFold);
  drawJoint(ctx, relx, rely, 3.5, CC.hoodieInner);
  const rwx = relx + Math.sin(pose.rUpper + pose.rFore) * CH.forearmL;
  const rwy = rely + Math.cos(pose.rUpper + pose.rFore) * CH.forearmL;
  drawSegment(ctx, relx, rely, rwx, rwy, CH.forearmW, CC.skin, CC.skinShadow);
  drawHand(ctx, rwx, rwy, CC.skin);

  ctx.restore();
}

