517	/* =========================== 精灵绘制 =========================== */
518	/* 涂鸦标签 -- 在指定位置绘制随机涂鸦 */
519	function drawGraffitiTag(ctx, x, y, w, h) {
520	  const colors = ['#ff3366','#ff6600','#ffcc00','#33ff66','#33ccff','#ff33cc','#aaff00','#ff0066'];
521	  const bgColors = ['#1a1a2e','#2a1a4e','#1a3a2e','#3a1a2e','#2a2a4e'];
522	
523	  /* 背景色块（涂鸦底板） */
524	  const bg = randChoice(bgColors);
525	  ctx.fillStyle = bg;
526	  ctx.fillRect(x, y, w, h);
527	  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
528	  ctx.lineWidth = 1;
529	  ctx.strokeRect(x, y, w, h);
530	
531	  /* 涂鸦文字/图案 */
532	  const tagColor = randChoice(colors);
533	  ctx.fillStyle = tagColor;
534	
535	  /* 随机选择涂鸦风格 */
536	  const style = randInt(0, 4);
537	  const cx = x + w/2, cy = y + h/2;
538	
539	  if (style === 0) {
540	    /* 气泡字体风格 -- 重叠的圆 */
541	    ctx.globalAlpha = 0.8;
542	    for (let i = 0; i < 5; i++) {
543	      const bx = x + 10 + Math.random() * (w - 20);
544	      const by = y + 10 + Math.random() * (h - 20);
545	      const br = 8 + Math.random() * 15;
546	      ctx.beginPath(); ctx.arc(bx, by, br, 0, Math.PI*2); ctx.fill();
547	    }
548	    ctx.globalAlpha = 1;
549	  } else if (style === 1) {
550	    /* 喷漆线条 -- 粗犷的水平条纹 */
551	    ctx.lineWidth = 4 + Math.random() * 8;
552	    ctx.strokeStyle = tagColor;
553	    for (let i = 0; i < 4; i++) {
554	      ctx.beginPath();
555	      const ly = y + 10 + i * h/4;
556	      ctx.moveTo(x + 5, ly);
557	      ctx.lineTo(x + w - 5, ly + (Math.random()-0.5)*10);
558	      ctx.stroke();
559	    }
560	  } else if (style === 2) {
561	    /* 箭头/三角形涂鸦 */
562	    ctx.beginPath();
563	    ctx.moveTo(cx, cy - h*0.3);
564	    ctx.lineTo(cx + w*0.35, cy + h*0.25);
565	    ctx.lineTo(cx - w*0.35, cy + h*0.25);
566	    ctx.closePath(); ctx.fill();
567	    /* 内圈 */
568	    ctx.fillStyle = bg;
569	    ctx.beginPath(); ctx.arc(cx, cy + h*0.05, w*0.12, 0, Math.PI*2); ctx.fill();
570	  } else if (style === 3) {
571	    /* 星形/爆炸 */
572	    const spikes = randInt(5, 8);
573	    ctx.beginPath();
574	    for (let i = 0; i < spikes * 2; i++) {
575	      const r = i % 2 === 0 ? Math.min(w,h)*0.4 : Math.min(w,h)*0.15;
576	      const angle = (i / (spikes * 2)) * Math.PI * 2 - Math.PI/2;
577	      const px = cx + Math.cos(angle) * r;
578	      const py = cy + Math.sin(angle) * r;
579	      if (i === 0) ctx.moveTo(px, py);
580	      else ctx.lineTo(px, py);
581	    }
582	    ctx.closePath(); ctx.fill();
583	  } else {
584	    /* 滴落风格 -- 垂直线条 + 圆点 */
585	    const drops = randInt(3, 7);
586	    for (let i = 0; i < drops; i++) {
587	      const dx = x + w * (0.2 + Math.random() * 0.6);
588	      ctx.beginPath();
589	      ctx.moveTo(dx, y + 5);
590	      ctx.lineTo(dx, y + h * (0.3 + Math.random() * 0.5));
591	      ctx.lineWidth = 3 + Math.random() * 4;
592	      ctx.strokeStyle = randChoice(colors);
593	      ctx.stroke();
594	      ctx.beginPath();
595	      ctx.arc(dx, y + h * (0.3 + Math.random() * 0.5), 3 + Math.random()*5, 0, Math.PI*2);
596	      ctx.fillStyle = randChoice(colors);
597	      ctx.fill();
598	    }
599	  }

