1617	      const s = worldToScreen(d);
1618	      const lx = laneX(lane, d);
1619	      ctx.beginPath();
1620	      ctx.moveTo(lx - 10, s.y);
1621	      ctx.lineTo(lx + 10, s.y);
1622	      ctx.stroke();
1623	    }
1624	  }
1625	}
