1627	/* =========================== 绘制障碍物 =========================== */
1628	function drawObstacle(ctx, obs, sx, sy, scale) {
1629	  ctx.save();
1630	  ctx.translate(sx, sy);
1631	  ctx.scale(scale, scale);
1632	
1633	  /* 直接绘制——绕开离屏精灵定位问题 */
1634	  if (obs.type === OBS_LOW) {
1635	    /* 道口横栏（低障碍） */
1636	    /* 支柱 */ ctx.fillStyle = '#555';
1637	    ctx.fillRect(-4, -16, 8, 24); ctx.fillRect(-22, -12, 8, 12); ctx.fillRect(14, -12, 8, 12);
1638	    /* 横杆 */ ctx.fillStyle = '#222';
1639	    ctx.fillRect(-30, -4, 60, 10);
1640	    /* 警示条纹 */ ctx.fillStyle = '#ffcc00';
1641	    ctx.fillRect(-28, -2, 6, 6); ctx.fillRect(-16, -2, 6, 6); ctx.fillRect(-4, -2, 6, 6);
1642	    ctx.fillRect(8, -2, 6, 6); ctx.fillRect(20, -2, 6, 6);
1643	    /* 红白交替 */ ctx.fillStyle = '#ff3333';
1644	    ctx.fillRect(-28, 1, 6, 4); ctx.fillRect(-16, 1, 6, 4); ctx.fillRect(-4, 1, 6, 4);
1645	    ctx.fillRect(8, 1, 6, 4); ctx.fillRect(20, 1, 6, 4);
1646	    ctx.fillStyle = '#fff';
1647	    ctx.fillRect(-22, 1, 6, 4); ctx.fillRect(-10, 1, 6, 4); ctx.fillRect(2, 1, 6, 4);
1648	    ctx.fillRect(14, 1, 6, 4); ctx.fillRect(26, 1, 6, 4);
1649	  } else if (obs.type === OBS_MID) {
1650	    /* 低矮障碍物——明显矮于人物，可跳跃通过 */
1651	    ctx.fillStyle = '#555';
1652	    ctx.fillRect(-20, -20, 40, 30);           // 矮箱体
1653	    ctx.fillStyle = '#ff6600';
1654	    ctx.fillRect(-16, -16, 32, 6);             // 橙色警示条
1655	    ctx.fillStyle = '#fff';
1656	    ctx.fillRect(-16, -8, 32, 4);              // 白色反光条
1657	    ctx.fillStyle = '#333';
1658	    ctx.fillRect(-6, 10, 6, 8);                // 左支脚
1659	    ctx.fillRect(2, 10, 6, 8);                 // 右支脚
1660	    /* 顶部闪烁灯 */
1661	    ctx.fillStyle = '#ffaa00';
1662	    ctx.beginPath(); ctx.arc(0, -24, 4, 0, Math.PI*2); ctx.fill();
1663	  } else if (obs.type === OBS_HIGH) {
1664	    /* 高压信号塔（高障碍） */
1665	    ctx.fillStyle = '#444';
1666	    ctx.fillRect(-14, -55, 28, 100);
1667	    /* 金属框架 */ ctx.strokeStyle = '#666'; ctx.lineWidth = 2;
1668	    ctx.strokeRect(-14, -55, 28, 100);
1669	    /* 叉形结构 */ ctx.strokeStyle = '#555'; ctx.lineWidth = 1.5;
1670	    ctx.beginPath(); ctx.moveTo(-14, -35); ctx.lineTo(14, -15); ctx.stroke();
1671	    ctx.beginPath(); ctx.moveTo(14, -35); ctx.lineTo(-14, -15); ctx.stroke();
1672	    ctx.beginPath(); ctx.moveTo(-14, 5); ctx.lineTo(14, 25); ctx.stroke();
1673	    ctx.beginPath(); ctx.moveTo(14, 5); ctx.lineTo(-14, 25); ctx.stroke();
1674	    /* 警示灯 */ ctx.fillStyle = '#ff0000';
1675	    ctx.beginPath(); ctx.arc(0, -48, 4, 0, Math.PI*2); ctx.fill();
1676	    /* 红白条纹段 */
1677	    for (let sy = -55; sy < 45; sy += 14) {
1678	      ctx.fillStyle = (Math.floor((sy+55)/14) % 2 === 0) ? '#cc3333' : '#ffffff';
1679	      ctx.fillRect(-13, sy + 1, 26, 5);
1680	    }
1681	    /* 宽底座 */ ctx.fillStyle = '#333';
1682	    ctx.fillRect(-8, 45, 16, 6);
1683	  }
1684	
1685	  ctx.restore();
1686	}
1687	
1688	/* =========================== 绘制金币 =========================== */
1689	function drawCoin(ctx, coin, sx, sy, scale) {
1690	  ctx.save();
1691	  ctx.translate(sx, sy);
1692	  const rot = (G.frameCount * 0.05 + coin.dist * 0.1) % (Math.PI * 2);
1693	  const squish = Math.abs(Math.cos(rot));
1694	  ctx.scale(squish * scale, scale);
1695	  ctx.fillStyle = "#ffaa00";
1696	  ctx.beginPath(); ctx.arc(0, 0, 12, 0, Math.PI * 2); ctx.fill();
1697	  ctx.fillStyle = "#ffdd44";
1698	  ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI * 2); ctx.fill();
1699	  ctx.fillStyle = "#ffe680";
1700	  ctx.beginPath(); ctx.arc(-2, -2, 3, 0, Math.PI * 2); ctx.fill();
1701	  ctx.restore();
1702	}
1703	
1704	
1705	function drawPowerup(ctx, pu, sx, sy, scale) {
1706	  ctx.save();
1707	  ctx.translate(sx, sy + Math.sin(pu.floatPhase) * 4 * scale);
1708	  const sz = 14 * scale;
1709	  /* 光晕 */
1710	  ctx.shadowColor = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffdd00';
1711	  ctx.shadowBlur = 10 * scale;
1712	  /* 外壳 */
1713	  ctx.fillStyle = 'rgba(255,255,255,0.85)';
1714	  ctx.beginPath();
1715	  ctx.arc(0, 0, sz, 0, Math.PI * 2);
1716	  ctx.fill();
1717	  ctx.shadowBlur = 0;
1718	  /* 图标（简化版用字母） */
1719	  ctx.fillStyle = pu.type === PUP_MAGNET ? '#ff44ff' : pu.type === PUP_SHIELD ? '#44aaff' : '#ffaa00';
1720	  ctx.font = `bold ${Math.floor(14*scale)}px "Segoe UI","PingFang SC",sans-serif`;
1721	  ctx.textAlign = 'center';
1722	  ctx.textBaseline = 'middle';
1723	  const ico = pu.type === PUP_MAGNET ? 'M' : pu.type === PUP_SHIELD ? 'S' : 'x2';
1724	  ctx.fillText(ico, 0, 0);
1725	  ctx.restore();
