1727	/* =========================== 绘制玩家 =========================== */
1728	function drawPlayer(ctx) {
1729	  const p = G.player;
1730	  ctx.save();
1731	  ctx.translate(p.x, p.y);
1732	
1733	  // 无敌闪烁
1734	  let alpha = 1;
1735	  if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
1736	    alpha = 0.35;
1737	  }
1738	
1739	  // 阴影
1740	  ctx.fillStyle = 'rgba(0,0,0,0.25)';
1741	  ctx.beginPath();
