1753	/* =========================== HUD =========================== */
1754	function drawHUD(ctx) {
1755	  if (G.state !== 'playing' && G.state !== 'dead') return;
1756	
1757	  /* 左上——血量 */
1758	  const heartSize = 18;
1759	  for (let i = 0; i < MAX_HEARTS; i++) {
1760	    const hx = 16 + i * (heartSize + 6);
1761	    const hy = 16;
1762	    if (i < G.hearts) {
1763	      /* 满血——红色心 */
1764	      drawHeart(ctx, hx, hy, heartSize, '#e94560');
1765	    } else {
1766	      /* 空血——灰色 */
1767	      drawHeart(ctx, hx, hy, heartSize, '#444');
1768	    }
1769	  }
1770	
1771	  /* 顶部居中——分数 */
1772	  ctx.fillStyle = '#fff';
1773	  ctx.font = 'bold 28px "Segoe UI","PingFang SC",sans-serif';
1774	  ctx.textAlign = 'center';
1775	  ctx.shadowColor = 'rgba(0,0,0,0.6)';
1776	  ctx.shadowBlur = 4;
1777	  ctx.fillText(Math.floor(G.score), G.W / 2, 40);
1778	  ctx.shadowBlur = 0;
1779	
1780	  /* 右上——速度指示 */
1781	  const speedPct = Math.floor((G.speed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED) * 100);
1782	  ctx.fillStyle = speedPct > 70 ? '#ff6644' : '#aaccff';
1783	  ctx.font = '12px "Segoe UI","PingFang SC",sans-serif';
1784	  ctx.textAlign = 'right';
1785	  ctx.fillText('速度 ' + speedPct + '%', G.W - 14, 28);
1786	
1787	  /* DEBUG：障碍物/金币统计 */
1788	  let activeObs = 0, activeCoins = 0;
1789	  for (let i = 0; i < G.obstacles.length; i++) if (G.obstacles[i].active) activeObs++;
1790	  for (let i = 0; i < G.coins.length; i++) if (G.coins[i].active) activeCoins++;
1791	  ctx.fillStyle = '#0f0';
1792	  ctx.font = '11px monospace';
1793	  ctx.textAlign = 'left';
1794	  ctx.fillText('DEBUG obs:' + activeObs + ' coins:' + activeCoins + ' dist:' + Math.floor(G.distance) + 'm spawn:' + Math.floor(G.spawnTimer) + '/' + Math.floor(G.spawnInterval/(G.speed/BASE_SPEED)), 12, G.H - 10);
1795	
1796	  /* 道具指示器 */
1797	  const pu = G.player;
1798	  if (pu.activePowerup || pu.hasShield) {
1799	    const puy = 60;
1800	    /* 护盾 */
1801	    if (pu.hasShield) {
1802	      ctx.fillStyle = '#44aaff';
1803	      ctx.font = 'bold 14px "Segoe UI","PingFang SC",sans-serif';
1804	      ctx.textAlign = 'right';
1805	      ctx.fillText('护盾', G.W - 14, puy);
1806	    }
1807	    /* 活动道具计时条 */
1808	    if (pu.activePowerup) {
1809	      const barW = 80, barH = 6;
1810	      const barX = G.W - 14 - barW, barY = puy + 4;
1811	      const pct = pu.powerupTimer / POWERUP_DURATION;
1812	      ctx.fillStyle = 'rgba(255,255,255,0.2)';
1813	      ctx.fillRect(barX, barY, barW, barH);
1814	      const barColor = pu.activePowerup === PUP_MAGNET ? '#ff44ff' :
1815	                       pu.activePowerup === PUP_2X ? '#ffdd00' : '#44aaff';
1816	      ctx.fillStyle = barColor;
1817	      ctx.fillRect(barX, barY, barW * pct, barH);
1818	      /* 标签 */
1819	      const label = pu.activePowerup === PUP_MAGNET ? '磁铁' : '2x分数';
1820	      ctx.fillStyle = '#fff';
1821	      ctx.font = 'bold 12px "Segoe UI","PingFang SC",sans-serif';
1822	      ctx.textAlign = 'right';
1823	      ctx.fillText(label, G.W - 14, puy);
1824	    }
1825	  }
1826	}
1827	
1828	function drawHeart(ctx, x, y, size, color) {
1829	  ctx.fillStyle = color;
1830	  ctx.beginPath();
1831	  const s = size / 20;
1832	  ctx.moveTo(x, y + size * 0.35);
1833	  /* 左半 */
1834	  ctx.bezierCurveTo(x, y + size*0.15, x - size*0.45, y - size*0.15, x - size*0.45, y + size*0.25);
1835	  ctx.bezierCurveTo(x - size*0.45, y + size*0.6, x, y + size*0.8, x, y + size);
1836	  /* 右半 */
1837	  ctx.bezierCurveTo(x, y + size*0.8, x + size*0.45, y + size*0.6, x + size*0.45, y + size*0.25);
1838	  ctx.bezierCurveTo(x + size*0.45, y - size*0.15, x, y + size*0.15, x, y + size*0.35);
1839	  ctx.fill();
1840	}
1841	
1842	/* =========================== 界面 =========================== */
1843	function drawStartScreen(ctx) {
1844	  /* 半透明遮罩 */
1845	  ctx.fillStyle = 'rgba(0,0,0,0.55)';
1846	  ctx.fillRect(0, 0, G.W, G.H);
1847	
1848	  /* 标题 */
1849	  ctx.fillStyle = '#fff';
1850	  ctx.font = 'bold 48px "Segoe UI","PingFang SC",sans-serif';
1851	  ctx.textAlign = 'center';
1852	  ctx.shadowColor = '#e94560';
1853	  ctx.shadowBlur = 20;
1854	  ctx.fillText('轨道跑者', G.W/2, G.H * 0.3);
1855	  ctx.shadowBlur = 0;
1856	
1857	  ctx.fillStyle = '#ffcc00';
1858	  ctx.font = 'bold 18px "Segoe UI","PingFang SC",sans-serif';
1859	  ctx.fillText('RAIL RUNNER', G.W/2, G.H * 0.3 + 40);
1860	
1861	  /* 操作说明 */
1862	  ctx.fillStyle = '#ddd';
1863	  ctx.font = '16px "Segoe UI","PingFang SC",sans-serif';
1864	  const instructions = [
1865	    '← →  切换轨道',
1866	    '↑  跳跃  |  ↓  滑铲',
1867	    '空格键  开始 / 重来',
1868	  ];
1869	  instructions.forEach((txt, i) => {
1870	    ctx.fillText(txt, G.W/2, G.H * 0.55 + i * 28);
1871	  });
1872	
1873	  /* 最高分 */
1874	  if (G.highScore > 0) {
1875	    ctx.fillStyle = '#ffdd44';
1876	    ctx.font = 'bold 20px "Segoe UI","PingFang SC",sans-serif';
1877	    ctx.fillText('最高分: ' + G.highScore, G.W/2, G.H * 0.74);
1878	  }
1879	
1880	  /* 提示 */
1881	  const alpha = 0.5 + 0.5 * Math.sin(G.frameCount * 0.05);
1882	  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
1883	  ctx.font = '18px "Segoe UI","PingFang SC",sans-serif';
1884	  ctx.fillText('点击屏幕 或 按空格键 开始', G.W/2, G.H * 0.85);
1885	}
1886	
1887	function drawDeathScreen(ctx) {
1888	  /* 半透明遮罩 */
1889	  ctx.fillStyle = 'rgba(0,0,0,0.6)';
1890	  ctx.fillRect(0, 0, G.W, G.H);
1891	
1892	  /* 得分面板背景 */
1893	  const panelW = G.W * 0.7;
1894	  const panelH = G.H * 0.35;
1895	  const panelX = (G.W - panelW) / 2;
1896	  const panelY = G.H * 0.25;
1897	  ctx.fillStyle = 'rgba(20,20,40,0.9)';
1898	  ctx.strokeStyle = '#e94560';
1899	  ctx.lineWidth = 2;
1900	  roundRect(ctx, panelX, panelY, panelW, panelH, 16);
1901	  ctx.fill();
1902	  ctx.stroke();
1903	
1904	  /* 标题 */
1905	  ctx.fillStyle = '#e94560';
1906	  ctx.font = 'bold 28px "Segoe UI","PingFang SC",sans-serif';
1907	  ctx.textAlign = 'center';
1908	  ctx.fillText('游戏结束', G.W/2, panelY + 45);
1909	
1910	  /* 本次得分 */
1911	  ctx.fillStyle = '#fff';
1912	  ctx.font = 'bold 24px "Segoe UI","PingFang SC",sans-serif';
1913	  ctx.fillText('得分: ' + Math.floor(G.score), G.W/2, panelY + 80);
1914	
1915	  /* 距离 */
1916	  ctx.fillStyle = '#aaa';
1917	  ctx.font = '16px "Segoe UI","PingFang SC",sans-serif';
1918	  ctx.fillText('距离: ' + Math.floor(G.distance) + ' 米', G.W/2, panelY + 108);
1919	
1920	  /* 最高分 */
1921	  const isNew = G.score >= G.highScore && G.highScore > 0;
1922	  ctx.fillStyle = isNew ? '#ffdd44' : '#aaa';
1923	  ctx.font = 'bold 18px "Segoe UI","PingFang SC",sans-serif';
1924	  ctx.fillText((isNew ? '🎉 新纪录！' : '最高分: ') + G.highScore, G.W/2, panelY + 135);
1925	
1926	  /* 重来提示 */
1927	  const alpha = 0.5 + 0.5 * Math.sin(G.frameCount * 0.06);
1928	  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
1929	  ctx.font = '18px "Segoe UI","PingFang SC",sans-serif';
1930	  ctx.fillText('点击屏幕 或 按空格键 重来', G.W/2, panelY + panelH + 40);
1931	}
1932	
1933	function roundRect(ctx, x, y, w, h, r) {
1934	  ctx.beginPath();
1935	  ctx.moveTo(x + r, y);
1936	  ctx.lineTo(x + w - r, y);
1937	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
1938	  ctx.lineTo(x + w, y + h - r);
1939	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
1940	  ctx.lineTo(x + r, y + h);
1941	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
1942	  ctx.lineTo(x, y + r);
1943	  ctx.quadraticCurveTo(x, y, x + r, y);
1944	  ctx.closePath();
1945	}
1946	
1947	/* =========================== 游戏主循环 =========================== */
1948	function gameLoop(timestamp) {
1949	  G.deltaTime = timestamp - G.lastTime;
1950	  G.lastTime = timestamp;
1951	
1952	  /* FPS 计算 */
1953	  G.frameCount++;
1954	  G.fpsFrameCount++;
1955	  G.fpsTime += G.deltaTime;
1956	  if (G.fpsTime >= 1000) {
1957	    G.fps = G.fpsFrameCount;
1958	    G.fpsFrameCount = 0;
1959	    G.fpsTime = 0;
1960	  }
1961	
1962	  processInput();
1963	  update();
1964	  render();
1965	  requestAnimationFrame(gameLoop);
1966	}
1967	
1968	/* =========================== 启动 =========================== */
1969	init();
1970	</script>
1971	</body>
1972	</html>
