/* ========================================================================
   骨骼动画角色系统 v2 — 纯背视图
   角色面朝屏幕深处（消失点方向）奔跑，镜头从正后上方观看。
   下肢交替伸展/折叠 + 躯干弹跳 + 手臂前后摆动 = 向前奔跑感。
   透视：远处的腿/臂略短且偏上方，近处的腿/臂略长且偏下方。
   ======================================================================== */

const CC = {
  skin:'#ffd3b6', skinS:'#e8bfa5',
  hair:'#2a1a0a', hairH:'#3d2818',
  hoodie:'#e94560', hoodieD:'#c23152', hoodieF:'#d63852',
  pants:'#2d2d44', pantsD:'#252538',
  shoe:'#f0f0f0', sole:'#333', shoeA:'#e94560',
  goggle:'#88ccff', goggleF:'#555', goggleH:'rgba(255,255,255,0.4)',
  eyeW:'#fff', pupil:'#1a1a1a', mouthC:'#c44',
};

/* 辅助：圆角段 */
function seg(ctx,x1,y1,x2,y2,w,c,d){
  const dx=x2-x1,dy=y2-y1,len=Math.sqrt(dx*dx+dy*dy);
  if(len<0.3)return;
  ctx.save();ctx.translate(x1,y1);ctx.rotate(Math.atan2(dy,dx));
  ctx.fillStyle=c;
  ctx.beginPath();const r=w/2;
  ctx.moveTo(r,-r);ctx.lineTo(len-r,-r);
  ctx.quadraticCurveTo(len,-r,len,0);
  ctx.quadraticCurveTo(len,r,len-r,r);
  ctx.lineTo(r,r);ctx.quadraticCurveTo(0,r,0,0);ctx.quadraticCurveTo(0,-r,r,-r);
  ctx.fill();
  if(d){ctx.fillStyle=d;ctx.fillRect(0,0,len,r);}
  ctx.restore();
}
function jnt(ctx,x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}
function ell(ctx,x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}

/* 鞋——背视图（看到鞋底和鞋跟） */
function shoeB(ctx,x,y,ang,flip){
  ctx.save();ctx.translate(x,y);ctx.rotate(ang);if(flip)ctx.scale(-1,1);
  ctx.fillStyle=CC.shoe;
  ctx.beginPath();ctx.moveTo(-5,-3);ctx.lineTo(8,-3);ctx.quadraticCurveTo(10,0,8,3);ctx.lineTo(-5,3);ctx.quadraticCurveTo(-7,0,-5,-3);ctx.fill();
  ctx.fillStyle=CC.sole;ctx.fillRect(-5,2,13,3);
  ctx.fillStyle=CC.shoeA;ctx.fillRect(0,2,1.5,3);
  ctx.restore();
}

/* ========== 主绘制 ========== */
function drawCharacter(ctx, x, y, state, frameCount, celebrateType, celebrateTimer) {
  const pl = G.player;
  const ph = ((frameCount * 0.13) % 1) * Math.PI * 2;
  const sinP = Math.sin(ph), cosP = Math.cos(ph);

  /* ---- 根据状态确定姿态 ---- */
  let lean, bounce, twist, lExt, rExt, lBend, rBend, lArm, rArm, hTilt, face;
  let bodyY = 0; // 躯干整体 Y 偏移（滑铲用）

  if (state === STATE_RUN && celebrateTimer > 0 && celebrateType) {
    const bt = celebrateType === 'lookback' ? 40 : 35;
    const cp = 1 - celebrateTimer / bt, cs = Math.sin(cp * Math.PI);
    lean = -0.05; bounce = 2; twist = 0; face = 'back';
    if (celebrateType === 'lookback') {
      lExt = 0.88; rExt = 0.88; lBend = 0.02; rBend = 0.02;
      lArm = -0.15; rArm = 0.15; hTilt = 0; twist = 0.4 * cs;
      if (cs > 0.5) face = 'left'; // 头转过半→露脸
    } else {
      lExt = 0.9; rExt = 0.9; lBend = 0; rBend = 0.7 * cs;
      lArm = -0.3; rArm = 0.5; hTilt = 0;
    }
  } else if (state === STATE_RUN) {
    lean = 0.13; bounce = Math.abs(sinP) * 6; twist = sinP * 0.06; face = 'back';
    lExt = 0.85 + sinP * 0.15; rExt = 0.85 - sinP * 0.15;
    lBend = Math.max(0, -sinP) * 0.6; rBend = Math.max(0, sinP) * 0.6;
    lArm = -sinP * 0.4; rArm = sinP * 0.4;
    hTilt = sinP * 0.03;
  } else if (state === STATE_JUMP) {
    const jp = 1 - pl.stateTimer / 150, tuck = Math.sin(jp * Math.PI);
    lean = 0.18; bounce = 0; twist = 0; face = 'back';
    lExt = 0.55 - tuck * 0.25; rExt = 0.55 - tuck * 0.25;
    lBend = 0.55 + tuck * 0.35; rBend = 0.55 + tuck * 0.35;
    lArm = -1.0 + tuck * 0.4; rArm = 1.0 - tuck * 0.4;
    hTilt = 0.1;
  } else if (state === STATE_SLIDE) {
    const sp = pl.stateTimer / 100;
    lean = -0.55; bounce = 0; twist = 0; face = 'back'; bodyY = -22;
    lExt = 0.65; rExt = 1.35; lBend = 0.15; rBend = 0.5;
    lArm = 0.3; rArm = 0.55; hTilt = 0.2;
  } else if (state === STATE_HIT) {
    lean = -0.3; bounce = -4; twist = 0; face = 'hurt';
    lExt = 0.8; rExt = 0.7; lBend = 0.2; rBend = 0.3;
    lArm = -1.6; rArm = -1.4; hTilt = -0.25;
  } else {
    lean = 0.13; bounce = 3; twist = 0; face = 'back';
    lExt = 0.85; rExt = 0.85; lBend = 0; rBend = 0;
    lArm = 0; rArm = 0; hTilt = 0;
  }

  ctx.save();
  ctx.translate(x, y + bodyY);

  const hipY = -14;
  const thighL = 18, calfL = 16;

  /* ======== 阴影 ======== */
  ell(ctx, 0, 11, 18, 5, 'rgba(0,0,0,0.22)');

  /* ======== 左腿（远侧，先画） ======== */
  (function(){
    const hx = -5.5;
    const thAng = -(0.12 + lExt * 0.28);
    const knX = hx + Math.sin(thAng) * thighL * 0.18;
    const knY = hipY + bounce + Math.cos(thAng) * thighL;
    seg(ctx, hx, hipY + bounce, knX, knY, 6, CC.pants, CC.pantsD);
    jnt(ctx, knX, knY, 3, CC.pantsD);
    const caAng = thAng + lBend * 0.8;
    const anX = knX + Math.sin(caAng) * calfL * 0.12;
    const anY = knY + Math.cos(caAng) * calfL;
    seg(ctx, knX, knY, anX, anY, 5, CC.pants, CC.pantsD);
    shoeB(ctx, anX, anY, caAng + 0.15, false);
  })();

  /* ======== 右腿（近侧） ======== */
  (function(){
    const hx = 5.5;
    const thAng = -(0.12 + rExt * 0.28);
    const knX = hx + Math.sin(thAng) * thighL * 0.18;
    const knY = hipY + bounce + Math.cos(thAng) * thighL;
    seg(ctx, hx, hipY + bounce, knX, knY, 6, CC.pants, CC.pantsD);
    jnt(ctx, knX, knY, 3, CC.pantsD);
    const caAng = thAng + rBend * 0.8;
    const anX = knX + Math.sin(caAng) * calfL * 0.12;
    const anY = knY + Math.cos(caAng) * calfL;
    seg(ctx, knX, knY, anX, anY, 5, CC.pants, CC.pantsD);
    shoeB(ctx, anX, anY, caAng + 0.15, false);
  })();

  /* ======== 躯干 + 头部 + 手臂（整体 lean + twist） ======== */
  ctx.save();
  ctx.translate(0, hipY + bounce);
  ctx.rotate(lean + twist);

  const shldW = 15, hipW2 = 9;
  const torsoTop = -30, torsoBot = -1;

  /* 躯干梯形——连帽衫背视图 */
  ctx.fillStyle = CC.hoodie;
  ctx.beginPath();
  ctx.moveTo(-shldW, torsoTop + 3);
  ctx.lineTo(-hipW2, torsoBot);
  ctx.lineTo(hipW2, torsoBot);
  ctx.lineTo(shldW, torsoTop + 3);
  ctx.closePath(); ctx.fill();

  /* 兜帽（垂在背后） */
  ctx.fillStyle = CC.hoodieD;
  ctx.beginPath();
  ctx.moveTo(-shldW + 2, torsoTop + 3);
  ctx.quadraticCurveTo(-shldW - 4, torsoTop - 9, -3, torsoTop - 12);
  ctx.quadraticCurveTo(0, torsoTop - 18, 3, torsoTop - 12);
  ctx.quadraticCurveTo(shldW + 4, torsoTop - 9, shldW - 2, torsoTop + 3);
  ctx.fill();
  /* 兜帽内衬 */
  ctx.fillStyle = CC.hoodieF;
  ctx.beginPath(); ctx.arc(0, torsoTop - 10, 8, 0, Math.PI); ctx.fill();

  /* 脊椎线 */
  ctx.strokeStyle = CC.hoodieD; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, torsoTop + 1); ctx.lineTo(0, torsoBot - 2); ctx.stroke();

  /* 褶皱 */
  ctx.strokeStyle = CC.hoodieF; ctx.lineWidth = 0.7;
  for (let i = 0; i < 3; i++) {
    const fy = torsoTop + 7 + i * 7;
    ctx.beginPath(); ctx.moveTo(-shldW + 5, fy);
    ctx.quadraticCurveTo(0, fy + (i % 2) * 3, shldW - 5, fy); ctx.stroke();
  }

  /* 腰带/裤腰 */
  ctx.fillStyle = CC.pantsD;
  ctx.fillRect(-hipW2 - 1, torsoBot - 1, hipW2 * 2 + 2, 4);

  const shldY = torsoTop + 5;

  /* ---- 左臂（远侧） ---- */
  (function(){
    const sx = -shldW + 2, uaL = 14, faL = 12;
    const uaAng = -0.35 + lArm;
    const ex = sx + Math.sin(uaAng) * uaL * 0.35;
    const ey = shldY + Math.cos(uaAng) * uaL;
    seg(ctx, sx, shldY, ex, ey, 5, CC.hoodie, CC.hoodieD);
    jnt(ctx, ex, ey, 2.6, CC.hoodieD);
    const faAng = uaAng - 0.35;
    const wx = ex + Math.sin(faAng) * faL * 0.25;
    const wy = ey + Math.cos(faAng) * faL;
    seg(ctx, ex, ey, wx, wy, 4, CC.skin, CC.skinS);
    jnt(ctx, wx, wy, 2.8, CC.skin);
  })();

  /* ---- 头部 ---- */
  (function(){
    const headCY = torsoTop - 4;
    ctx.fillStyle = CC.skinS; ctx.fillRect(-2.5, headCY - 3, 5, 5); // 脖子

    if (face === 'left') {
      /* 左侧脸——回头 */
      ctx.fillStyle = CC.skin;
      ctx.beginPath(); ctx.arc(-3, headCY - 9, 9.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = CC.hair;
      ctx.beginPath(); ctx.arc(-4, headCY - 14, 10, Math.PI, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = CC.eyeW;
      ctx.beginPath(); ctx.arc(-6, headCY - 10, 2.2, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = CC.pupil;
      ctx.beginPath(); ctx.arc(-7, headCY - 10, 1.1, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = CC.goggle;
      ctx.beginPath(); ctx.arc(-6, headCY - 13, 3.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = CC.goggleH;
      ctx.beginPath(); ctx.arc(-7, headCY - 14, 1.2, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = CC.mouthC; ctx.lineWidth = 0.8;
      ctx.beginPath(); ctx.arc(-7, headCY - 8, 2, 0.2, Math.PI - 0.2); ctx.stroke();
    } else if (face === 'hurt') {
      /* 受击——头后仰 */
      ctx.fillStyle = CC.skin;
      ctx.beginPath(); ctx.arc(0, headCY - 8, 9, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = CC.hair;
      ctx.beginPath(); ctx.arc(0, headCY - 12, 10, Math.PI, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = CC.eyeW;
      ctx.beginPath(); ctx.arc(-3, headCY - 9, 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(3, headCY - 9, 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = CC.pupil;
      ctx.beginPath(); ctx.arc(-2, headCY - 10, 0.8, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(4, headCY - 10, 0.8, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = CC.mouthC; ctx.lineWidth = 0.8;
      ctx.beginPath(); ctx.arc(0, headCY - 5, 3, 0.3, Math.PI - 0.3); ctx.stroke();
    } else {
      /* 背视图——后脑勺 */
      ell(ctx, 0, headCY - 9, 9, 10.5, CC.skin);
      ctx.fillStyle = CC.hair;
      ctx.beginPath(); ctx.arc(0, headCY - 14, 10, Math.PI, 2 * Math.PI); ctx.fill();
      ctx.beginPath(); ctx.arc(0, headCY - 4, 9, 0, Math.PI); ctx.fill();
      ctx.fillStyle = CC.hairH;
      ctx.beginPath(); ctx.arc(-2, headCY - 14, 3, 0, Math.PI * 2); ctx.fill();
      /* 耳朵 */
      ell(ctx, -9, headCY - 7, 2.2, 3, CC.skin);
      ell(ctx, 9, headCY - 7, 2.2, 3, CC.skin);
      /* 护目镜带——绕头后 */
      ctx.strokeStyle = CC.goggleF; ctx.lineWidth = 1.8;
      ctx.beginPath(); ctx.moveTo(-10, headCY - 8);
      ctx.quadraticCurveTo(0, headCY - 2, 10, headCY - 8); ctx.stroke();
    }
  })();

  /* ---- 右臂（近侧，后画以遮挡躯干） ---- */
  (function(){
    const sx = shldW - 2, uaL = 14, faL = 12;
    const uaAng = -0.35 + rArm;
    const ex = sx + Math.sin(uaAng) * uaL * 0.35;
    const ey = shldY + Math.cos(uaAng) * uaL;
    seg(ctx, sx, shldY, ex, ey, 5, CC.hoodie, CC.hoodieD);
    jnt(ctx, ex, ey, 2.6, CC.hoodieD);
    const faAng = uaAng - 0.35;
    const wx = ex + Math.sin(faAng) * faL * 0.25;
    const wy = ey + Math.cos(faAng) * faL;
    seg(ctx, ex, ey, wx, wy, 4, CC.skin, CC.skinS);
    jnt(ctx, wx, wy, 2.8, CC.skin);
  })();

  ctx.restore(); // lean+twist
  ctx.restore(); // main translate
}

