610	/* ========================================================================
611	   预渲染精灵表角色系统 — 纯背视图，8帧跑步循环
612	   每帧在 80x100 离屏 Canvas 上预绘制，运行时直接 drawImage。
613	   跑步循环：接触→下沉→经过→蹬起 × 2（左右脚交替）
614	   外加跳跃/滑铲/受击/庆祝专用帧。
615	   ======================================================================== */
616	
617	const SP = { // Sprite Palette
618	  skin:'#ffd3b6', skinS:'#e8bfa5',
619	  hair:'#2a1a0a', hairH:'#3d2818',
620	  hoodie:'#e94560', hoodieD:'#c23152', hoodieF:'#d63852',
621	  pants:'#2d2d44', pantsD:'#252538',
622	  shoe:'#f0f0f0', sole:'#333', shoeA:'#e94560',
623	  goggleF:'#555',
624	};
625	
626	/* 在 80x100 画布上绘制单帧角色 */
627	function drawSpritePose(ctx, pose) {
628	  const W = 80, H = 100;
629	  ctx.clearRect(0, 0, W, H);
630	  const cx = 40; // 水平居中
631	  const hipY = 52 + pose.bounce;
632	  const shldY = hipY - 28;
633	  const headY = shldY - 16;
634	  const shldW = 16, hipW = 9;
635	
636	  const { lLeg, rLeg, lArm, rArm, headTurn } = pose;
637	
638	  /* ---- 阴影 ---- */
639	  ctx.fillStyle = 'rgba(0,0,0,0.18)';
640	  ctx.beginPath(); ctx.ellipse(cx, hipY + 34, 14, 4, 0, 0, Math.PI * 2); ctx.fill();
641	
642	  /* ---- 远侧腿（先画，被躯干遮挡） ---- */
643	  drawLimb(ctx, cx - 5, hipY, lLeg.hipA, lLeg.kneeA, 16, 14, SP.pants, SP.pantsD, 6.5, 5.5);
644	  /* 远侧鞋 */
645	  const lf = footPos(cx - 5, hipY, lLeg.hipA, lLeg.kneeA, 16, 14);
646	  drawShoe(ctx, lf.x, lf.y, lf.ang);
647	
648	  /* ---- 远侧臂 ---- */
649	  const lfa = armPos(cx - shldW + 2, shldY + 4, lArm.shldA, lArm.elbowA, 13, 11);
650	  drawLimb(ctx, cx - shldW + 2, shldY + 4, lArm.shldA, lArm.elbowA, 13, 11, SP.hoodie, SP.hoodieD, 5, 4);
651	  ctx.fillStyle = SP.skin; ctx.beginPath(); ctx.arc(lfa.x, lfa.y, 3, 0, Math.PI * 2); ctx.fill();
652	
653	  /* ---- 躯干（梯形连帽衫） ---- */
654	  ctx.save();
655	  ctx.translate(cx, hipY);
656	  ctx.rotate(pose.lean || 0);
657	
658	  /* 躯干 */
659	  ctx.fillStyle = SP.hoodie;
660	  ctx.beginPath();
661	  ctx.moveTo(-shldW, -27); ctx.lineTo(-hipW, 0);
662	  ctx.lineTo(hipW, 0); ctx.lineTo(shldW, -27);
663	  ctx.closePath(); ctx.fill();
664	
665	  /* 兜帽（垂在背后） */
666	  ctx.fillStyle = SP.hoodieD;
667	  ctx.beginPath();
668	  ctx.moveTo(-shldW + 2, -27);
669	  ctx.quadraticCurveTo(-shldW - 3, -34, -4, -36);
670	  ctx.quadraticCurveTo(0, -43, 4, -36);
671	  ctx.quadraticCurveTo(shldW + 3, -34, shldW - 2, -27);
672	  ctx.fill();
673	  ctx.fillStyle = SP.hoodieF;
674	  ctx.beginPath(); ctx.arc(0, -34, 7, 0, Math.PI); ctx.fill();
675	
676	  /* 脊椎线 */
677	  ctx.strokeStyle = SP.hoodieD; ctx.lineWidth = 0.8;
678	  ctx.beginPath(); ctx.moveTo(0, -26); ctx.lineTo(0, -3); ctx.stroke();
679	
680	  /* 腰带 */
681	  ctx.fillStyle = SP.pantsD;
682	  ctx.fillRect(-hipW - 1, -2, hipW * 2 + 2, 4);
683	
684	  /* ---- 头部 ---- */
685	  {
686	    const hcy = -30;
687	    ctx.fillStyle = SP.skinS;
688	    ctx.fillRect(-2.5, hcy + 1, 5, 4); // 脖子
689	
690	    if (headTurn === 'left') {
691	      /* 回头露左脸 */
692	      ctx.fillStyle = SP.skin;
693	      ctx.beginPath(); ctx.arc(-3, hcy - 9, 9, 0, Math.PI * 2); ctx.fill();
694	      ctx.fillStyle = SP.hair;
695	      ctx.beginPath(); ctx.arc(-4, hcy - 13, 9.5, Math.PI, 2 * Math.PI); ctx.fill();
696	      ctx.fillStyle = '#fff';
