}
/* ========================================================================
   预渲染精灵表角色系统 — 纯背视图，8帧跑步循环
   每帧在 80x100 离屏 Canvas 上预绘制，运行时直接 drawImage。
   跑步循环：接触→下沉→经过→蹬起 × 2（左右脚交替）
   外加跳跃/滑铲/受击/庆祝专用帧。
   ======================================================================== */

const SP = { // Sprite Palette
  skin:'#ffd3b6', skinS:'#e8bfa5',
  hair:'#2a1a0a', hairH:'#3d2818',
  hoodie:'#e94560', hoodieD:'#c23152', hoodieF:'#d63852',
  pants:'#2d2d44', pantsD:'#252538',
  shoe:'#f0f0f0', sole:'#333', shoeA:'#e94560',
  goggleF:'#555',
};

/* 在 80x100 画布上绘制单帧角色 */
function drawSpritePose(ctx, pose) {
  const W = 80, H = 100;
  ctx.clearRect(0, 0, W, H);
  const cx = 40; // 水平居中
  const hipY = 52 + pose.bounce;
  const shldY = hipY - 28;
  const headY = shldY - 16;
  const shldW = 16, hipW = 9;

  const { lLeg, rLeg, lArm, rArm, headTurn } = pose;

  /* ---- 阴影 ---- */
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  ctx.beginPath(); ctx.ellipse(cx, hipY + 34, 14, 4, 0, 0, Math.PI * 2); ctx.fill();

  /* ---- 远侧腿（先画，被躯干遮挡） ---- */
  drawLimb(ctx, cx - 5, hipY, lLeg.hipA, lLeg.kneeA, 16, 14, SP.pants, SP.pantsD, 6.5, 5.5);
  /* 远侧鞋 */
  const lf = footPos(cx - 5, hipY, lLeg.hipA, lLeg.kneeA, 16, 14);
  drawShoe(ctx, lf.x, lf.y, lf.ang);

  /* ---- 远侧臂 ---- */
  const lfa = armPos(cx - shldW + 2, shldY + 4, lArm.shldA, lArm.elbowA, 13, 11);
  drawLimb(ctx, cx - shldW + 2, shldY + 4, lArm.shldA, lArm.elbowA, 13, 11, SP.hoodie, SP.hoodieD, 5, 4);
  ctx.fillStyle = SP.skin; ctx.beginPath(); ctx.arc(lfa.x, lfa.y, 3, 0, Math.PI * 2); ctx.fill();

  /* ---- 躯干（梯形连帽衫） ---- */
  ctx.save();
  ctx.translate(cx, hipY);
  ctx.rotate(pose.lean || 0);

  /* 躯干 */
  ctx.fillStyle = SP.hoodie;
  ctx.beginPath();
  ctx.moveTo(-shldW, -27); ctx.lineTo(-hipW, 0);
  ctx.lineTo(hipW, 0); ctx.lineTo(shldW, -27);
  ctx.closePath(); ctx.fill();

  /* 兜帽（垂在背后） */
  ctx.fillStyle = SP.hoodieD;
  ctx.beginPath();
  ctx.moveTo(-shldW + 2, -27);
  ctx.quadraticCurveTo(-shldW - 3, -34, -4, -36);
  ctx.quadraticCurveTo(0, -43, 4, -36);
  ctx.quadraticCurveTo(shldW + 3, -34, shldW - 2, -27);
  ctx.fill();
  ctx.fillStyle = SP.hoodieF;
  ctx.beginPath(); ctx.arc(0, -34, 7, 0, Math.PI); ctx.fill();

  /* 脊椎线 */
  ctx.strokeStyle = SP.hoodieD; ctx.lineWidth = 0.8;
  ctx.beginPath(); ctx.moveTo(0, -26); ctx.lineTo(0, -3); ctx.stroke();

  /* 腰带 */
  ctx.fillStyle = SP.pantsD;
  ctx.fillRect(-hipW - 1, -2, hipW * 2 + 2, 4);

  /* ---- 头部 ---- */
  {
    const hcy = -30;
    ctx.fillStyle = SP.skinS;
    ctx.fillRect(-2.5, hcy + 1, 5, 4); // 脖子

    if (headTurn === 'left') {
      /* 回头露左脸 */
      ctx.fillStyle = SP.skin;
      ctx.beginPath(); ctx.arc(-3, hcy - 9, 9, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = SP.hair;
      ctx.beginPath(); ctx.arc(-4, hcy - 13, 9.5, Math.PI, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(-6, hcy - 10, 2, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(-7, hcy - 10, 1, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#88ccff';
      ctx.beginPath(); ctx.arc(-6, hcy - 13, 3.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      ctx.beginPath(); ctx.arc(-7, hcy - 14, 1.2, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#c44'; ctx.lineWidth = 0.6;
      ctx.beginPath(); ctx.arc(-7, hcy - 7, 1.8, 0.2, Math.PI - 0.2); ctx.stroke();
      /* 耳 */
      ctx.fillStyle = SP.skin;
      ctx.beginPath(); ctx.ellipse(-11, hcy - 7, 2, 2.8, 0, 0, Math.PI * 2); ctx.fill();
    } else if (headTurn === 'hurt') {
      ctx.fillStyle = SP.skin;
      ctx.beginPath(); ctx.arc(0, hcy - 7, 8.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = SP.hair;
      ctx.beginPath(); ctx.arc(0, hcy - 11, 9.5, Math.PI, 2 * Math.PI); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(-3, hcy - 8, 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(3, hcy - 8, 1.5, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#1a1a1a';
      ctx.beginPath(); ctx.arc(-2, hcy - 9, 0.8, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(4, hcy - 9, 0.8, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#c44'; ctx.lineWidth = 0.6;
      ctx.beginPath(); ctx.arc(0, hcy - 4, 2.5, 0.3, Math.PI - 0.3); ctx.stroke();
    } else {
      /* 背视图——后脑勺 */
      ctx.fillStyle = SP.skin;
      ctx.beginPath(); ctx.ellipse(0, hcy - 8, 8.5, 10, 0, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = SP.hair;
      ctx.beginPath(); ctx.arc(0, hcy - 13, 9.5, Math.PI, 2 * Math.PI); ctx.fill();
      ctx.beginPath(); ctx.arc(0, hcy - 3, 8.5, 0, Math.PI); ctx.fill();
      ctx.fillStyle = SP.hairH;
      ctx.beginPath(); ctx.arc(-2, hcy - 13, 2.8, 0, Math.PI * 2); ctx.fill();
      /* 耳朵 */
      ctx.fillStyle = SP.skin;
      ctx.beginPath(); ctx.ellipse(-8.5, hcy - 6, 2, 2.7, 0, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.ellipse(8.5, hcy - 6, 2, 2.7, 0, 0, Math.PI * 2); ctx.fill();
      /* 护目镜带 */
      ctx.strokeStyle = SP.goggleF; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(-9, hcy - 7);
      ctx.quadraticCurveTo(0, hcy - 2, 9, hcy - 7); ctx.stroke();
    }
  }

  ctx.restore(); // lean

  /* ---- 近侧臂 ---- */
  const rfa = armPos(cx + shldW - 2, shldY + 4, rArm.shldA, rArm.elbowA, 13, 11);
  drawLimb(ctx, cx + shldW - 2, shldY + 4, rArm.shldA, rArm.elbowA, 13, 11, SP.hoodie, SP.hoodieD, 5, 4);
  ctx.fillStyle = SP.skin; ctx.beginPath(); ctx.arc(rfa.x, rfa.y, 3, 0, Math.PI * 2); ctx.fill();

  /* ---- 近侧腿 ---- */
  drawLimb(ctx, cx + 5, hipY, rLeg.hipA, rLeg.kneeA, 16, 14, SP.pants, SP.pantsD, 6.5, 5.5);
  const rf = footPos(cx + 5, hipY, rLeg.hipA, rLeg.kneeA, 16, 14);
  drawShoe(ctx, rf.x, rf.y, rf.ang);

  /* ---- 运动线（速度感） ---- */
  if (pose.motionLines) {
    ctx.strokeStyle = 'rgba(255,255,255,0.25)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const mx = 40 + (i - 1) * 18;
      ctx.beginPath(); ctx.moveTo(mx, hipY + 30); ctx.lineTo(mx, hipY + 42); ctx.stroke();
    }
  }
}

/* 肢体绘制：从原点出发，第一段角度 a1 长度 l1，第二段角度 a1+a2 长度 l2 */
function drawLimb(ctx, ox, oy, a1, a2, l1, l2, c1, c2, w1, w2) {
  const jx = ox + Math.sin(a1) * l1 * 0.22;
  const jy = oy + Math.cos(a1) * l1;
  thickLine(ctx, ox, oy, jx, jy, w1, c1);
  const ex = jx + Math.sin(a1 + a2) * l2 * 0.22;
  const ey = jy + Math.cos(a1 + a2) * l2;
  thickLine(ctx, jx, jy, ex, ey, w2, c2);
  /* 关节 */
  ctx.fillStyle = c2;
  ctx.beginPath(); ctx.arc(jx, jy, w2 * 0.45, 0, Math.PI * 2); ctx.fill();
}

function footPos(ox, oy, a1, a2, l1, l2) {
  const jx = ox + Math.sin(a1) * l1 * 0.22;
  const jy = oy + Math.cos(a1) * l1;
  return {
    x: jx + Math.sin(a1 + a2) * l2 * 0.22,
    y: jy + Math.cos(a1 + a2) * l2,
    ang: a1 + a2
  };
}

function armPos(ox, oy, a1, a2, l1, l2) {
  const jx = ox + Math.sin(a1) * l1 * 0.30;
  const jy = oy + Math.cos(a1) * l1;
  return {
    x: jx + Math.sin(a1 + a2) * l2 * 0.28,
    y: jy + Math.cos(a1 + a2) * l2
  };
}

function thickLine(ctx, x1, y1, x2, y2, w, c) {
  const dx = x2 - x1, dy = y2 - y1, len = Math.sqrt(dx * dx + dy * dy);
  if (len < 0.3) return;
  ctx.save(); ctx.translate(x1, y1); ctx.rotate(Math.atan2(dy, dx));
  ctx.fillStyle = c;
  const r = w / 2;
  ctx.beginPath();
  ctx.moveTo(r, -r); ctx.lineTo(len - r, -r);
  ctx.quadraticCurveTo(len, -r, len, 0);
  ctx.quadraticCurveTo(len, r, len - r, r);
  ctx.lineTo(r, r);
  ctx.quadraticCurveTo(0, r, 0, 0);
  ctx.quadraticCurveTo(0, -r, r, -r);
  ctx.fill();
  ctx.restore();
}

function drawShoe(ctx, x, y, ang) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(ang + 0.15);
  ctx.fillStyle = SP.shoe;
  ctx.beginPath();
  ctx.moveTo(-4, -2); ctx.lineTo(7, -2);
  ctx.quadraticCurveTo(9, 0, 7, 2.5); ctx.lineTo(-4, 2.5);
  ctx.quadraticCurveTo(-6, 0, -4, -2);
  ctx.fill();
  ctx.fillStyle = SP.sole; ctx.fillRect(-4, 1.5, 11, 2.5);
  ctx.fillStyle = SP.shoeA; ctx.fillRect(1, 1.5, 1.5, 2.5);
  ctx.restore();
}

/* 8帧跑步循环定义
   每帧角度参数：hipA=大腿角(0=垂直向下,正=前摆), kneeA=膝角(正=弯曲)

}

/* 8帧跑步循环定义
   每帧角度参数：hipA=大腿角(0=垂直向下,正=前摆), kneeA=膝角(正=弯曲)
   shldA=上臂角(0=垂直向下,正=前摆), elbowA=肘角(正=弯曲)
   跑步循环阶段：接触(contact)→下沉(down)→经过(passing)→蹬起(up)→接触(另一脚) */
const RUN_POSES = [
  // Frame 0: 右脚接触 — 右腿前伸着地，左腿后蹬
  { bounce: -1, lean: 0.07, headTurn: 'back',
    lLeg: { hipA: -0.55, kneeA: 0.40 }, rLeg: { hipA: 0.38, kneeA: 0.05 },
    lArm: { shldA: 0.55, elbowA: 0.35 }, rArm: { shldA: -0.45, elbowA: 0.35 } },
  // Frame 1: 右腿下沉 — 承重屈膝，左腿前摆
  { bounce: -3, lean: 0.06, headTurn: 'back',
    lLeg: { hipA: -0.25, kneeA: 0.65 }, rLeg: { hipA: 0.20, kneeA: 0.45 },
    lArm: { shldA: 0.40, elbowA: 0.55 }, rArm: { shldA: -0.60, elbowA: 0.25 } },
  // Frame 2: 经过位 — 左腿经过支撑腿，右腿蹬伸
  { bounce: 0, lean: 0.08, headTurn: 'back',
    lLeg: { hipA: 0.10, kneeA: 0.70 }, rLeg: { hipA: -0.15, kneeA: 0.15 },
    lArm: { shldA: 0.05, elbowA: 0.50 }, rArm: { shldA: -0.30, elbowA: 0.55 } },
  // Frame 3: 右脚蹬起 — 右腿后蹬离地，左腿高抬前摆
  { bounce: 2, lean: 0.09, headTurn: 'back',
    lLeg: { hipA: 0.40, kneeA: 0.55 }, rLeg: { hipA: -0.50, kneeA: 0.25 },
    lArm: { shldA: -0.20, elbowA: 0.45 }, rArm: { shldA: 0.30, elbowA: 0.50 } },
  // Frame 4: 左脚接触 — 左腿前伸着地，右腿后蹬（镜像帧0）
  { bounce: -1, lean: 0.07, headTurn: 'back',
    lLeg: { hipA: 0.38, kneeA: 0.05 }, rLeg: { hipA: -0.55, kneeA: 0.40 },
    lArm: { shldA: -0.45, elbowA: 0.35 }, rArm: { shldA: 0.55, elbowA: 0.35 } },
  // Frame 5: 左腿下沉 — 承重屈膝，右腿前摆（镜像帧1）
  { bounce: -3, lean: 0.06, headTurn: 'back',
    lLeg: { hipA: 0.20, kneeA: 0.45 }, rLeg: { hipA: -0.25, kneeA: 0.65 },
    lArm: { shldA: -0.60, elbowA: 0.25 }, rArm: { shldA: 0.40, elbowA: 0.55 } },
  // Frame 6: 经过位 — 右腿经过，左腿蹬伸（镜像帧2）
  { bounce: 0, lean: 0.08, headTurn: 'back',
